(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["2-6"] = [{"a": [117], "v": 1, "p": 302, "ev": 1, "ep": 303, "sid": 303, "t": "قوله - عز وجل -:\n﴿بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَإِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ﴾⟪2:117⟫\nالآية (117) - سورة البقرة.\nالبديع: يقال للمبدع والمبدع جميعا، والإبداع إيجاد فعل ابتداء لا احتذاء، ولهذا قيل: فلان بدع في كذا، وجدل البدعة اسما لكل مخترع لم يؤثر عن أرباب الشرع.\nوالقضاء: إتمام الشر قولا أو فعلا، فمن القول قوله تعالى: ﴿وَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُ﴾⟪17:23⟫، ﴿وَقَضَيۡنَآ إِلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ فِي ٱلۡكِتَٰبِ﴾⟪17:4⟫، ومن الفعل قوله: ﴿فَقَضَىٰهُنَّ سَبۡعَ سَمَٰوَاتٖ فِي يَوۡمَيۡنِ﴾⟪41:12⟫ وقضى فلان دينه، وقضى\nنحبه، وانقضى الأمر، وتقضى بلغ أخره، ذكره تعالى هذه الآية حجة رابعة شرحها أن الأب هو عنصر للابن، منه تكون، والله مبدع الأشياء كلها، فلا يكون عنصرا للولد، فمن المحال أن يكون المنفعل فاعلا، وخص لفظ الإبداع لكونه أبلغ لفظا وأبعده عن الاحتمال، وذلك أن أفعال الله تعالى على ثلاثة أوجه: إبداع وهو \" اختراع \" الشيء لا عن شيء ولا في زمان، ويستعمل ذلك في إيجاده تعالى المبادئ، و \" صنع \" وهو تركيب صورة مع العنصر، وتستعمل في إيجاده الأجسام، و \" تسخير \" وهو سوق الشيء إلى غرضه المقصود منه طوعا أو قهرا، ويستعمل في القوى التي أوجدها في السحاب والأمطار والأغذية والأدوية، وكل هذه الثلاثة يقال له الخلق، وأقدمها الإبداع، ونبه بقوله: ﴿قَضَىٰٓ أَمۡرٗا﴾⟪2:117⟫ على حجة خامسة ، وهو أن الولد يكون بنشر وتركيب حالا بعد حال، وهو إذا أراد شيئا فقد فعل بلا مهلة ولم يرد \" بإذا \" حقيقة الزمان، إذ كان ذلك إشارة إلى ما قبل وجود الزمان، ولم يرد أيضا \" بكن \" حقيقة اللفظ ولا بالفاء التعقيب الزماني، بل استعير كل ذلك ولأنه أقرب ما يتراءى لنا به سرعة الفصل وتمامه، وذكر لفظ \" القضاء \"، إذ هو لإتمام الفعل.\nوالآخر لكونه منطويا على اللفظ والفعل\n⟦1:303⟧\nوالقول إذ هو أخف موجد منا وأسرعه إيجادا، ولفظ: \" كن \" لعموم معناه، واختصار [لفظه]، ثم قال: \" فيكون \"، تنبيها أنه لا يمتنع عليه شي يريد إيجاده، وكن فيكون، وإن كان مخرجها مخرج شيئين أحدهما مبني على والآخر، فهو في الحقيقة شيء واحد ونحوه قولنا: فلان إذا أراد شيئا فقد كان ما أراد، واختلق في تفسير هذه الآية من حيث إن \" كن \" لفظ أمرا والأمر لا يكون إلا لموجود، فبعض قال: \" لفظ الشر مخصوص \" ههنا للموجودين الذين قال لهم: ﴿كُونُواْ قِرَدَةً خَٰسِـِٔينَ﴾ وبعض قال: (هو خطاب لمن يجيبهم من الوتى)، وبعض قال: هو أمر للشيء في حال تكونه لا قبله ولا بعده، وبعض قال: هو أمر لمعلوم له، وذلك في حكم الموجود وإن كان معدوم الذات وبعض قال: \" هو أمر للمعدوم \"، قال: ويصح أمرا لمعدوم، كما يصح أمرا لموجود، وبعض قال: \" إنه جعل \" كن \" دلالة للملائكة على ما يتقضيه من الأفعال \"، وأكثر هذه الأقوال يتبين وهنه بتصور ما تقدم ..."}, {"a": [118], "v": 1, "p": 303, "ev": 1, "ep": 305, "sid": 304, "t": "قوله - عز وجل -:\n﴿وَقَالَ ٱلَّذِينَ لَا يَعۡلَمُونَ لَوۡلَا يُكَلِّمُنَا ٱللَّهُ أَوۡ تَأۡتِينَآ ءَايَةٞۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ مِن قَبۡلِهِم مِّثۡلَ قَوۡلِهِمۡۘ تَشَٰبَهَتۡ قُلُوبُهُمۡۗ قَدۡ بَيَّنَّا ٱلۡأٓيَٰتِ لِقَوۡمٖ يُوقِنُونَ﴾⟪2:118⟫\nالآية (118) - سورة البقرة\nاليقين أبلغ علم وأوكده، وهو أن يكون عالم بالشئ، وعالما بأنك تعلمه غير شاك ولا متهيئ للشك، ولذلك قيل: هو المعلوم الذي زالت عنه المعارضة على مرور الأوقات، وإنما لم يوصف الباري تعالى به من حيث أنه لا يستعمل إلا في العلم المكتسب، ولهذا قال تعالى في صفة إبراهيم- عليه السلام ﴿وَكَذَٰلِكَ نُرِيٓ إِبۡرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلِيَكُونَ مِنَ ٱلۡمُوقِنِينَ﴾⟪6:75⟫، ويعني بالذين لا يعلمون الكافرين على عهد رسول الله - صلى الله عليه وسلم - وقول ابن عباس: \" هم اليهود \"، وقول مجاهد: \" النصارى \"، وقول الحسن وقيادة: \" هم مشركو العرب كله محتمل ويصح أن يكونوا جميعا مرادين، فقد قال الله: ﴿يَسۡـَٔلُكَ أَهۡلُ ٱلۡكِتَٰبِ أَن تُنَزِّلَ عَلَيۡهِمۡ كِتَٰبٗا مِّنَ ٱلسَّمَآءِۚ فَقَدۡ سَأَلُواْ مُوسَىٰٓ أَكۡبَرَ مِن ذَٰلِكَ﴾⟪4:153⟫ ومشركو\n⟦1:304⟧\nالعرب قالوا: ﴿لَن نُّؤۡمِنَ لَكَ حَتَّىٰ تَفۡجُرَ لَنَا مِنَ ٱلۡأَرۡضِ يَنۢبُوعًا﴾⟪17:90⟫، وعني بالذين قبلهم من سبق من كافري الأمم، فقد قال أصحاب موسى: ﴿أَرِنَا ٱللَّهَ جَهۡرَةٗ﴾⟪4:153⟫ وأصحاب عيسى قالوا: ﴿أَنزِلۡ عَلَيۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِ﴾⟪5:114⟫ ثم بين أنهم متشابهون في العمي والجهالة، لاقتراحهم على رسلهم كقوله: ﴿أَتَوَاصَوۡاْ بِهِۦۚ بَلۡ هُمۡ قَوۡمٞ طَاغُونَ﴾⟪51:53⟫.\nإن قيل: إنهم وإن أخطأوا في قولهم: ﴿لَوۡلَا يُكَلِّمُنَا ٱللَّهُ﴾⟪2:118⟫ فإنهم لم\nيخطئوا في سؤال الآية، إذ لا يلزم الإنسان أن يؤمن إلا لمن يأتي بآية تدل على صدقه، قيل: إنما أنكر عليهم جحودهم الأيات التي آتاهم، ولذلك قال ﴿قَدۡ بَيَّنَّا ٱلۡأٓيَٰتِ﴾⟪2:118⟫ كما قالت: ﴿قَدۡ بَيَّنَّا ٱلۡأٓيَٰتِ﴾⟪2:118⟫ كما قال، ﴿وَقَالُواْ لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَٰتٞ مِّن رَّبِّهِۦۚ قُلۡ إِنَّمَا ٱلۡأٓيَٰتُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٞ مُّبِينٌ ۝ أَوَلَمۡ يَكۡفِهِمۡ أَنَّآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ يُتۡلَىٰ عَلَيۡهِمۡۚ﴾⟪29:50-51⟫، وقوله: ﴿لِقَوۡمٖ يُوقِنُونَ﴾⟪2:118⟫ فيه معنيان: أحدهما أنهم يطلبون اليقين وليس بهم المعاندة، والثاني: أن من حصل له اليقين بالحق المحض وليس يعتريه شبهة فله في القرآن لا آية بل\nآيات، كما قال: ﴿هُوَ لِلَّذِينَ ءَامَنُواْ هُدٗى وَشِفَآءٞۚ﴾⟪41:44⟫، وقرأ بعضهم: (تشابهت) بتشديد الشين، كأنه نظر إلى قوله: (تشابه)، فحمل عليه، وذلك خطأ، لأن تشابه أصله تتشابه، فأدعم، وليس في تشابهت ذلك، ومن قال: هلا أجابهم إلى سؤالهم في أثناء الآية؟: فسؤال جاهل بحكمة الله تعالى، فباقتراح جاهل، وتشويه لا يجوز للحكيم أن يفعل ما ينافي مقتضى الحكمة، وقد أزاح العلة بغير سؤالهم وإلى ذلك أشار بقوله: ﴿وَلَوِ ٱتَّبَعَ ٱلۡحَقُّ أَهۡوَآءَهُمۡ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ﴾⟪23:71⟫\n⟦1:305⟧"}, {"a": [119], "v": 1, "p": 305, "ev": 1, "ep": 305, "sid": 306, "t": "قوله - عز وجل -:\n﴿إِنَّآ أَرۡسَلۡنَٰكَ بِٱلۡحَقِّ بَشِيرٗا وَنَذِيرٗاۖ وَلَا تُسۡـَٔلُ عَنۡ أَصۡحَٰبِ ٱلۡجَحِيمِ﴾⟪2:119⟫\nالآية (119) - سورة البقرة.\nالجحيم المناحج من النار يقال نجحت النار، وشبه حمرة عين الأسد به، فقيل لها جحمة.\nوجاحم الحرب تشبيها، فبين تعالى أن عليك البشارة والإنذار، ولا يلزمك عقابهم تسلية له، كقوله:\n﴿فَلَا تَذۡهَبۡ نَفۡسُكَ عَلَيۡهِمۡ حَسَرَٰتٍۚ﴾⟪35:8⟫، وقوله ﴿لَّيۡسَ عَلَيۡكَ هُدَىٰهُمۡ﴾⟪2:272⟫، وقوله: ﴿مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُۗ﴾.\nوقوله: ﴿فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُ وَعَلَيۡنَا ٱلۡحِسَابُ﴾⟪13:40⟫، وقوله: ﴿وَلَا تُسۡـَٔلُ﴾⟪2:119⟫ قال معطوف على قوله ﴿بَشِيرٗا وَنَذِيرٗاۖ﴾⟪2:119⟫، وقرأ نافع (ولا تسئل)، بالجزم، فقيل ذلك تفخيما لشأنهم، وقيلت: نهى عن تتبع ما أغناه الله عنه من أخبار من مضى، وقد روي أنه عليه السلام كان يستغفر لأبيه، فنهاه الله تعالى عن ذلك، لقوله: ﴿مَا كَانَ لِلنَّبِيِّ وَٱلَّذِينَ ءَامَنُوٓاْ أَن يَسۡتَغۡفِرُواْ لِلۡمُشۡرِكِينَ وَلَوۡ كَانُوٓاْ أُوْلِي قُرۡبَىٰ﴾⟪9:113⟫."}, {"a": [120], "v": 1, "p": 305, "ev": 1, "ep": 307, "sid": 306, "t": "قوله - عز وجل -:\n﴿وَلَن تَرۡضَىٰ عَنكَ ٱلۡيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمۡۗ قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۗ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم بَعۡدَ ٱلَّذِي جَآءَكَ مِنَ ٱلۡعِلۡمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِيّٖ وَلَا نَصِيرٍ﴾⟪2:120⟫\nالآية (120) - سورة البقرة.\nالملة: من أمللت الكتاب، وهي اسم لما شرعه الله تعالي لعباده على لسان أنبيائه ليتوصلوا به إلي آجل ثوابه، والدين ملة، لكن الملة تقال باعتبار دعا الله وإنزال كتبه والدين باعتبار طاعة العباد له بإجابة دعائه والانقياد لأمره، والشيء الواحد قد يسمى باسمين على اعتبارين، ثم تقال المله والدين لما\n⟦1:306⟧\nلم يكن من قبل الله على التقييد، كقولك: \" ملة مزدك وغيره \"، والهوى: رأي عن شهوة داع إلى الضلال وسمي بذلك لأنه يهوي بصاحبه في الدنيا إلى كل داهية، وهي الآخرة إلى الهاوية، ولهذا سميت النار هاوية، ولشدة سلطانه وصفة الله بأنة إله الكفار، فقال: ﴿أَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ﴾⟪45:23⟫، ومعنى الآية أن من خالفوك لا يرضون عنك إلا بمتابعة ملتهم تنبيها أنه لا يرضيهم إلا ما لا يجوز وقوعه منك، ثم بين أن إتباعهم ليس بهدى، وأن الهدى هو هدي الله، أي إرشاده، كقوله ﴿مَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِيۖ﴾⟪7:178⟫، ثم حذره فقال: ﴿وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم﴾⟪2:120⟫، وذلك تحذير له ولأمته، ولكن خص بالذكر لأن أنبياء الله ، بل أولياءه بأدنى ميل إلى ضال يكونون في حكم تابعي هواهم.\nوربما بعد ذلك في جرائمهم الكبيرة ويؤاخذون بما لا يؤخذ غيرهم به، وذلك معلوم في التعارف، فإن من حصل له زلفة متناهية من السلطان لا يتجافى عما يقع منه من أدنى مخالفة كالتجافي عن الأجانب، ولهذا قيل: (كبائر الأولياء صغائر العوام)، وقيل: (فاحشة الأولياء التواني في تعهد الأنفاس، وفاحشة العوام فيما فيه المحدود) وإنما قال: أهواءهم بلفظ الجمع تنبيها على أن لكل هوى غير هوى الأخر، ثم هوى كل واحد منهم لا يتناهى، ونحو ذلك قوله: ﴿وَلَا تَتَّبِعۡ أَهۡوَآءَ ٱلَّذِينَ لَا يَعۡلَمُونَ﴾⟪45:18⟫، وقوله: ﴿قُل لَّآ أَتَّبِعُ أَهۡوَآءَكُمۡ قَدۡ ضَلَلۡتُ إِذٗا وَمَآ أَنَا۠ مِنَ ٱلۡمُهۡتَدِينَ﴾⟪6:56⟫، وقوله للمؤمنين: ﴿وَلَا تَتَّبِعُوٓاْ أَهۡوَآءَ قَوۡمٖ قَدۡ ضَلُّواْ مِن قَبۡلُ﴾⟪5:77⟫، وقال: ﴿وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِۚ﴾⟪38:26⟫، وذلك تحذير من الهوى جملة، وقد تعلق بهده الآية من يجعل الكفر كله ملة واحدة، لأنه جمع بين اليهود والنصارى، وسمي طريقتهما ملة واحدة\n....\n⟦1:307⟧"}, {"a": [121], "v": 1, "p": 307, "ev": 1, "ep": 308, "sid": 308, "t": "قوله - عز وجل -:\n﴿ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَتۡلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُوْلَٰٓئِكَ يُؤۡمِنُونَ بِهِۦۗ وَمَن يَكۡفُرۡ بِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ﴾⟪2:121⟫\nالآية (121) - سورة البقرة.\nقد تقدم الكلام في التلاوة، منها تكون بالقراءة تارة، وبتتبع العنف تارة، وباستعمال مقتضاه تارة، وهو المعنى بقوله: ﴿حَقَّ تِلَاوَتِهِۦٓ﴾⟪2:121⟫، وعليه دل قول ابن عباس وابن مسعود يتبعونه حق اتباعه، وقول مجاهدة \" يعملون به حق عمله \"، وقول عمر: \" حق تلاوته \": إذا ذكر الجنة سأل الله الجنة، وإذا ذكر النار تعود منها \"، وذلك عام في كتاب الله تعالى وفي أربابها، فقول قتاده: هم أصحالب النبي - صلى الله عليه وسلم - وقول ابن زيد: إنهم اليهود والنصارى، وقول غيرهما: هم الذين أسلموا من مشركي العرب كلها داخل فيه، وعموم اللفظ يقتضيه وقوله \" الذين \" مبتدأ، \" يتلونه \" حال لهم، و \" أولئك \" خبره، والمعنى: هم الذين يحصل لهم الإيمان به دون الذين ينكرونه، وليس لهم إلا الخسران البين، ونحو ذلك قوله تعالى: ﴿وَنُنَزِّلُ مِنَ ٱلۡقُرۡءَانِ مَا هُوَ شِفَآءٞ وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ وَلَا يَزِيدُ ٱلظَّٰلِمِينَ إِلَّا خَسَارٗا﴾⟪17:82⟫، وهذه الأية كالتحقيق لما تقدم من قوله: ﴿وَقَالَ ٱلَّذِينَ لَا يَعۡلَمُونَ لَوۡلَا يُكَلِّمُنَا ٱللَّهُ أَوۡ تَأۡتِينَآ ءَايَةٞۗ﴾⟪2:118⟫.\n⟦1:308⟧"}, {"a": [122, 123], "v": 1, "p": 308, "ev": 1, "ep": 308, "sid": 309, "t": "قوله - عز وجل -:\n﴿يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَنِّي فَضَّلۡتُكُمۡ عَلَى ٱلۡعَٰلَمِينَ ۝ وَٱتَّقُواْ يَوۡمٗا لَّا تَجۡزِي نَفۡسٌ عَن نَّفۡسٖ شَيۡـٔٗا وَلَا يُقۡبَلُ مِنۡهَا عَدۡلٞ وَلَا تَنفَعُهَا شَفَٰعَةٞ وَلَا هُمۡ يُنصَرُونَ﴾⟪2:122-123⟫\nالآيتان (122، 123) - سورة البقرة.\nقد تقدم الكلام في مضمون الآيتين، ويسأل عن فائدة تكريرها، وأنه قال في هذه الآية: {ولا يقبل منها عدل ولا تنفعها شفاعةوفي الآية المتقدمة قال: ﴿وَلَا يُقۡبَلُ مِنۡهَا شَفَٰعَةٞ وَلَا يُؤۡخَذُ مِنۡهَا عَدۡلٞ﴾⟪2:48⟫، والجواب: أما التكرير فعلى سبيل الإنذار، فالواعظ إذا وعظ لأمر ما قد يكرر الذي يعظ لأجله تعظيما لأمره، وأما تغيير النظم، فلما كان قبول العدل وأخذه وقبول الشفاعة ونفعها متلازمة، لم يكن بين اتفاق هذه العبارات واختلافها فرق في المعنى .."}, {"a": [124], "v": 1, "p": 308, "ev": 1, "ep": 311, "sid": 309, "t": "قوله- عز وجل:\n﴿وَإِذِ ٱبۡتَلَىٰٓ إِبۡرَٰهِـۧمَ رَبُّهُۥ بِكَلِمَٰتٖ فَأَتَمَّهُنَّۖ قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامٗاۖ قَالَ وَمِن ذُرِّيَّتِيۖ قَالَ لَا يَنَالُ عَهۡدِي ٱلظَّٰلِمِينَ﴾⟪2:124⟫\nالآية (124) - سورة البقرة.\nالابتلاء كالاختبار، لكن الابتلاء طلب إظهار الفعل، والاختبار طلب الخبر، وهما متلازمان، والتام والكامل والوافي والوافر متقاربة، لكن التام يقال للمعدود الممسوح جميعا، نحو عدد تام، وليل تام، ورجل تام الخلقة، والكمال أكثر ما يقال في الممسوح والمشبه به، وقوله: ﴿تِلۡكَ عَشَرَةٞ كَامِلَةٞۗ﴾⟪2:196⟫، فالمراد كمال الحكم لإكمال العدد، كما قدره بعض الملاحدة، فاعترض عليه بالإزراء.\n⟦1:309⟧\nوالوافي ما أشرف على الشيء، ومنه وفاء العهد، وأوفى على كدا، أي أشرف عليه، والوافر: ما لم ينقص منه شيء، ومنه الوفر، وسقاء أوفر لم ينقص من أديمه شيء والذرية: الأولاد الصغار والكبار، وقيل هي للصغار، وقيل أصله من الذر، وقالت الفراء: أصله من ذريت وذروت، وقال أبو عبيدة: أصله الهمز من ذرأ الله الخلق، فترك همزة على غير قياس، والإمام في الأصل: الختم به محقا كان أو مبطلا، منه قوله تعالى: ﴿يَوۡمَ نَدۡعُواْ كُلَّ أُنَاسِۭ بِإِمَٰمِهِمۡۖ﴾⟪17:71⟫، وقوله: ﴿وَجَعَلۡنَٰهُمۡ أَئِمَّةٗ يَدۡعُونَ إِلَى ٱلنَّارِۖ﴾⟪28:41⟫، وفي إطلاق الشرع اسم للمقتدي به، المقتدي بالشرع، وهو أعم من النبي والخليفة إذ كل نبي وخليفة: إمام، وليس كل إمام ونبي خليفة، والكلمات قد تقع على الألفاظ المنظومة وعلى المعاني التي تحتلها، فقوله: ﴿وَتَمَّتۡ كَلِمَتُ رَبِّكَ صِدۡقٗا وَعَدۡلٗاۚ لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦۚ﴾⟪6:115⟫ أي: قضيته وحكمه وقال: ﴿قُل لَّوۡ كَانَ ٱلۡبَحۡرُ مِدَادٗا لِّكَلِمَٰتِ رَبِّي﴾⟪18:109⟫ أي؟ للمعاني التي تبرز بالكلمات ولم يرد اللفظ، فإن ما يحصره اللفظ يحصره الخط، والكلمات التي ابتلى بها مبهمة محتملة، وذكر المفسرون لها وجوها يصح أن تكون كلها مراده، فقيل: هي عشر سنن، همس في الرأس المضمضة، والاستنشاق، والفرق، وقص الشارب، والسواك، وخمس في الجسد تقليم الأظافر، ونتف الأبط، والختان، وحلق العانة، والاستنجاء، وقيل: هي خصال محمودة ذكر بعضهما في سورة/ التوبة، وبعضها في سورة/ المؤمنون، وبعضهما في سورة/ سأل سائل، وقد تقدم ذكرها في قوله: ﴿فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٖ فَتَابَ عَلَيۡهِۚ﴾⟪2:37⟫ وقيل: هي مناسك الحج المذكورة في قوله: ﴿وَإِذۡ بَوَّأۡنَا لِإِبۡرَٰهِيمَ مَكَانَ ٱلۡبَيۡتِ﴾⟪22:26⟫ الآية، وكل ذلك عن ابن عباس، وقيل: في ابتلاؤه بالكوكب وبالقمر والشمس، وقيل: امتحانه بإنفاق ماله، وهجر أوطانه، وذبح ولده، وإلقائه في النار فلما لم يؤثر على اختبار الله في شيء من ذلك قال فيه: (فأتمهن)\n⟦1:310⟧\nوإتمامه: هو الوفاء بها المذكور في قوله: ﴿وَإِبۡرَٰهِيمَ ٱلَّذِي وَفَّىٰٓ﴾⟪53:37⟫، وسماه حنيفا مسلما، وقال: ﴿إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامٗاۖ﴾⟪2:124⟫، وجعل إمامته للناس كافة على التأييد، فإنه لم يبعث بعده نبي إلا من ذريته، كما قال تعالى: ﴿وَجَعَلۡنَا فِي ذُرِّيَّتِهِ ٱلنُّبُوَّةَ وَٱلۡكِتَٰبَ﴾⟪29:27⟫، وقال: ﴿وَجَعَلَهَا كَلِمَةَۢ بَاقِيَةٗ فِي عَقِبِهِۦ﴾⟪43:28⟫ حتى قال للنبي (محمد) عليه السلام: ﴿ثُمَّ أَوۡحَيۡنَآ إِلَيۡكَ أَنِ ٱتَّبِعۡ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۖ﴾⟪16:123⟫.\nوقال: ﴿مِّلَّةَ أَبِيكُمۡ إِبۡرَٰهِيمَۚ هُوَ سَمَّىٰكُمُ ٱلۡمُسۡلِمِينَ مِن قَبۡلُ﴾⟪22:78⟫، وأمر- عليه السلام- بذكر إبراهيم في الصلاة، فقال: \" اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم \"، ولم يرد بالإمامة ههنا النبوة كما ظنه بعض المفسرين، فإنه- عليه السلام- إمام للناس على العموم في كل زمان على الإطلاق وليس بنبي لهم على [العموم] بالإطلاق، ولا قيل له ذلك قال: ﴿وَمِن ذُرِّيَّتِيۖ﴾⟪2:124⟫، فأجيب إلى ملتمسه بقوله: ﴿لَا يَنَالُ عَهۡدِي ٱلظَّٰلِمِينَ﴾⟪2:124⟫ لكنه تعالى بين أنه قد يكون من ذريته ظالم، وبين أن الإمام يتحمل للعهد، والظالم لا عهد له، فإذا لا إمامة له، ولهذا ما روي في الخبر أن الله تعالى يقول يوم القيامة لوالي السوء: (ياداعي السوء، أكلت اللحم، وشربت اللبن، ولبست الصوف، ولم تؤد الكسير ولم ترعها في مرعاها)، واستدل بالآية بعض الناس، فزعم أن الظالم إدا عوهد لم يلزم الوفاء بعهده، وقال الحسن: \" إنما لم يجعل الله لهم عهدا \"\n....\n⟦1:311⟧"}, {"a": [125], "v": 1, "p": 311, "ev": 1, "ep": 312, "sid": 312, "t": "قوله - عز وجل -:\n﴿وَإِذۡ جَعَلۡنَا ٱلۡبَيۡتَ مَثَابَةٗ لِّلنَّاسِ وَأَمۡنٗا وَٱتَّخِذُواْ مِن مَّقَامِ إِبۡرَٰهِـۧمَ مُصَلّٗىۖ وَعَهِدۡنَآ إِلَىٰٓ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ أَن طَهِّرَا بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡعَٰكِفِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ﴾⟪2:125⟫\nالآية (125) - سورة البقرة.\nالبيت: يسمى اعتبارا بالمبيت فيه، ومنه قيل: بيتهم وبات يموت بات ليلته في إنائه، ثم ترك اعتبار المبيت، وللوعي صورته، وبه شبه بين الشعر اعتبارا بأنه مبني من أوتاد وأسباب بناء بيت الشعر والوبر من نحوها، وبيت الله: سمي لوجود صورة البيت فيه، والمثابة إما لثؤوب الناس إليه، وإما لاستحقاقهم الثواب بقصده.\nإن قيل: كيف جعل مثابا عامة قصاده لا يثوبون إليه قبل ذلك باعتبار جنس الناس لا بآحادهم، واعتبر بعض الناس ما سآلته، واستدل بالآية في وجوب العمرة، فقال: لا يكون مثابة لأحاد قصاده إلا على هذا الوجه، ومقام إبراهيم الحرم عن ابن عباس، والمزدلفة عن عطاء، والحجر عن السدى، والأولى أنه الحرم كله، فما من موضع ذكروه إلا وهو مصلى أي مدعى، أو بوضع صلاة، والطوف المشي حول الشيء، ومنه: الطائف يدور حول البيت حافظا، وطائف من الجن والخيال، وجعل الطوافون عباده عز الحرم، والعكوف: الإقامة مع اللزوم بين تعالى أنه جعل البيت من حيث الحكم مثابة للناس وأمنا ومصلى، ولم يعن أنهم ملجؤون إلى أن لا يخيفوا أحدا، كما لم يعن أنهم ملجؤون إلى أن يجعلوه مصلى ومثابة.\nإن قيل: فقد قال: ﴿فِيهِ ءَايَٰتُۢ بَيِّنَٰتٞ مَّقَامُ إِبۡرَٰهِيمَۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنٗاۗ﴾⟪3:97⟫، قيل: هو أيضا على معنى الأول، ولو عنى ما قلت لقال: (وإن من دخله كان آمنا) قيل : هو أيضا علي معنى الأول، ولو عنى ما قلت لقال: وإن من دخله حتى كان يتعلق بالأول، وعلى ذلك حكم قوله: ﴿أَوَلَمۡ يَرَوۡاْ أَنَّا جَعَلۡنَا حَرَمًا ءَامِنٗا وَيُتَخَطَّفُ ٱلنَّاسُ مِنۡ حَوۡلِهِمۡۚ﴾⟪29:67⟫ على أن حكم الله في ذلك مما فيه أية منه لأنه حض الناس على\n⟦1:312⟧\nاستعظام البيت حتى لا يجسر عامتهم على تعظيم حرمته، ومن ضيقها كان ممقوتا غير منفك من عقوبة أما متجلية للمناظر أو ظاهرة لأولي البصائر، وقرئ: \" واتخذوا \" على الأمر، وروي فيه أن النبي - صلى الله عليه وسلم - قال لعمر لما انتهى إلى المقام: \" هذا مقام أبينا إبراهيم، [فقال: ألا نتخذه مصلى؟] \" فأنزل الله- عز وجل- ﴿وَٱتَّخِذُواْ مِن مَّقَامِ إِبۡرَٰهِـۧمَ مُصَلّٗىۖ﴾⟪2:125⟫، فعلى هذا أمر فصل به بين الجملتين من الخبر المعطوفة، والمعطوف عليها، (وعهدنا إلى) أي، أمرناهما أمرا موثقا عليهما بأن يطهرا البيت من الأنجاس والشرك وكل ما ينافي موضع الطهارة، للطائفين: أي القصاد، وقيل لأولي الطواف، وكلاهما مراد، والركع السجود: المصلين، وقيل: قد دخل في الأمر بتطهيره أن ببنيانه على تقوى كما قال: ﴿أَفَمَنۡ أَسَّسَ بُنۡيَٰنَهُۥ عَلَىٰ تَقۡوَىٰ مِنَ ٱللَّهِ وَرِضۡوَٰنٍ خَيۡرٌ﴾⟪9:109⟫ الآية."}, {"a": [126], "v": 1, "p": 312, "ev": 1, "ep": 314, "sid": 313, "t": "قوله- عز وجل:\n﴿وَإِذۡ قَالَ إِبۡرَٰهِـۧمُ رَبِّ ٱجۡعَلۡ هَٰذَا بَلَدًا ءَامِنٗا وَٱرۡزُقۡ أَهۡلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنۡ ءَامَنَ مِنۡهُم بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلٗا ثُمَّ أَضۡطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِۖ وَبِئۡسَ ٱلۡمَصِيرُ﴾⟪2:126⟫\nالآية (126) - سورة البقرة.\nالبلد: الأثر الباقي، وسمي المدينة، وكركرة البعير.\nوالمفازة: بلدا للآثار الظاهر بها، وقيل للآثار في الجلد أبلاد، والبليد: المقيم على بلده أي مكانه، ثم جعل عبارة عمن لا نفاذ له في الأمر حتى صار أملك له، والمصير: المنتهي إليه في الأمر، ومنه المصير: لمنتهى الطعام، وصير البقرة مأواها، كالزريبة للغنم، وصير الباب: حيث مصيره، وإنما قيل: شق الباب اعتبارا بصورته لا بحقيقة مقتضي اللفظ، والاضطرار: حمل الإنسان على [ما يضره وهو في التعارف] حمل على الأمر بكره وذلك على وجهين: أحدهما بسبب خارج، وهو إما أن يضرب أو يهدد بالضرب حتى يفعله منقادا، وإما أن يؤخذ بيده فيفعل ذلك به، والثاني بسبب من داخل، وذلك إما بقهر قوة له لا يناله بدفعها الهلاك، كمن غلب\n⟦1:313⟧\nعليه شهوة خمر أو قمار، وأما بقهر قوة يناله بدفعها الهلاك كمن اشتد به الجوع، فاضطر إلى أكل الميتة أو تناول مال الغير، ولما بنى إبراهيم عليه السلام البيت في فقر، ومن شرط المدن أن يتحرى في بنائها موضع يمكن أن يجري فيه نهر أو يشق فيه قناة، ويتخذ فيه مزرعة تفي بمطاعم قطانها، وعلم أن لا قوام لهم إلا بأن تجنى إليهم الثمرات، ولا يمكن جني الثمرات إليهم إلا بأمنه، سأل الله عز وجل - أن يجعله بلدا أمنا بسياسة ألاهية وأن يرزق أهله بتسخير الناس لجبي الثمرات إليه ولما سأله لهم الرزق، وكان قد سمع في جواب سؤاله الإمامة لذريته ما سمع تدارك سؤاله فقيده وقال: ﴿مَنۡ ءَامَنَ مِنۡهُم بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ﴾⟪2:126⟫ فقال تعالى: ﴿وَمَن كَفَرَ﴾⟪2:126⟫ تنبيها أن رحمته في الدنيا وسعت كل شيء، وأن نعمه فيها متاحة للكل ليجعلوها ذريعة إلى إدراك ثوابه، ثم من كفر وضيع النعم فمسوق إلى عذابه.\nإن قيل: إن قوله (فأمتعه) يقتضي كثرة ثبات الفعل وقوله (قليلا) ينافيه، فكيف جمع بينهما؟ قيل: ذلك على وجهين، فإن نعمته في الدنيا وإن كانت كثيرة بإضافة بعضها إلى بعض، فقليلة بإضافتها إلى نعمة الآخرة، وعلى هذا قال: ﴿قُلۡ مَتَٰعُ ٱلدُّنۡيَا قَلِيلٞ﴾⟪4:77⟫، كيف لا يقل ما يتناهى بالإضافة إلى مالا يتناهى؟ وانتصاب \" قليل \" إما لكونه وصفا لمصدر محذوف أو لكونه ظرفا، وتكون في العبارة به عن الزمان، كقوله تعالى: ﴿عَمَّا قَلِيلٖ لَّيُصۡبِحُنَّ نَٰدِمِينَ﴾⟪23:40⟫.\n⟦1:314⟧"}, {"a": [127], "v": 1, "p": 314, "ev": 1, "ep": 315, "sid": 315, "t": "قوله - عز وجل:\n﴿وَإِذۡ يَرۡفَعُ إِبۡرَٰهِـۧمُ ٱلۡقَوَاعِدَ مِنَ ٱلۡبَيۡتِ وَإِسۡمَٰعِيلُ رَبَّنَا تَقَبَّلۡ مِنَّآۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ﴾⟪2:127⟫\nالآية (127) سورة البقرة.\nالرفع والوضع يتقابلان، ويقال في الأجسام وفي الشرف والذلة على التشبيه وكذلك يقال في الإعراب على التشبيه والقعود المقابل للقيام، ثم جعل للثبات، فقيل لأساس البيت قواعد عن طلب الشرف، والقعيدة كناية عن الزوجة اعتبارا بقعودها في المنزل، والقعدة للفرس المقتعد في أكثر الأحوال، والقعود من البعير المدرك اقتعاده، وقيل إن إبراهيم عليه السلام - كان يبني وإسماعيل يرفع إليه الأحجار ويناوله، وذلك لا يمنع من أن يكون الفعل منسوبا إليهما وقول من قال: يجب إن يكون إبراهيم يتولى بناءه مرة، وإسماعيل مرة حتى يصح نسبة الفعل إليهما فبعيد التصور لسعة مجال الألفاظ وما اختلف فيه أنه هل كان للبيت بناء قبل إبراهيم - عليه السلام -، فأعاده أو هو الذي أنشأه وأحدثه، فليس مما يفتقر معنى الآية إليه وقيل ليس يعنى برفعهما قواعد البناء فقط، بل تحريمها تشريفه بدعاء الناس إليه ودعاء الله بحفظه، وصح نسبة ذلك إليهما وإن كان الله تعالى في الحقيقة شرفه من حيث أنهما من الأسباب المتأخرة لتشريفه.\n⟦1:315⟧"}, {"a": [128], "v": 1, "p": 315, "ev": 1, "ep": 316, "sid": 316, "t": "قوله - عز وجل:\n﴿رَبَّنَا وَٱجۡعَلۡنَا مُسۡلِمَيۡنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةٗ مُّسۡلِمَةٗ لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبۡ عَلَيۡنَآۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ﴾⟪2:128⟫ الآية (128) - سورة البقرة.\nالنسك: غاية العبادة، والناسك الأخذ نفسه ببلوغ قاصيتها حسب طاقته، وسمي أعمال الحج المناسك ثم خص الذبيحة بالنسك وتعورف فيه حتى قيل نسك فلان أي ذبح وقيل للذبيحة نسيكة ولم يعن بالمسلم ههنا من حقن دمه بالشهادتين، كما ظن بعضهم وقال هذا دعاء بما علم كونه لهما لا محالة، وإنما عنى من ليس في فلبه تعظيم الله معه، وهو المعنى بالمضروب له المثل في قوله: ﴿وَرَجُلٗا سَلَمٗا لِّرَجُلٍ﴾⟪39:29⟫ وبقوله: ﴿إِلَّا مَنۡ أَتَى ٱللَّهَ بِقَلۡبٖ سَلِيمٖ﴾⟪26:89⟫ وقوله: ﴿تَوَفَّنِي مُسۡلِمٗا﴾⟪12:101⟫ وهذه قاصية الإيمان، ونبه تعالى بالآية أن من حق الإنسان أن يكون مع تحري الحق لا ينفك من التضرع إلى الله - عز وجل - بإرشاده وتوفيقه، ومن طلب أن يتوب عليه من ذنب عسى إن كان منه وهو غافل عنه\nفإن قيل: ولم قيد؟ فقال: ﴿وَمِن ذُرِّيَّتِنَآ أُمَّةٗ مُّسۡلِمَةٗ لَّكَ﴾⟪2:128⟫ ولم يعمم؟ قيل إن هذه منزلة شريفة لا يكاد يتخصص بها إلا الواحد فالواحد في برهة بعد برهة، وعلم أن الحكمة الإلاهية لا تقتضي ذلك، فإنه لو جعل الناس كلهم كذلك لما تمشى أمر العالم إذ كان العالم يفتقر إلى كون أفاضل فيها وأوساط وأراذل لتولي عمارته والقيام بتمشية أموره فقد قيل: عمارة الدنيا بثلاثة أشياء، أحدها الزراعة والغرس، والثاني: في الحماية والحرب، والثالث جلب الأشياء من مصر إلى مصر، وأنبياء الله لا يصلحون لذلك إذ كانوا بغرض أخر أشرف من ذلك ولهذا قيل: \" لولا الحمقى لخربت الدنيا \" وإنما عني بالحمقى المعنيون بأمر الدنيا بإضافته إلى المعنيين بأمر الآخرة، ولذلك قال ﴿وَٱسۡتَعۡمَرَكُمۡ فِيهَا﴾⟪11:61⟫\n⟦1:316⟧"}, {"a": [129], "v": 1, "p": 316, "ev": 1, "ep": 317, "sid": 317, "t": "قوله - عز وجل -:\n﴿رَبَّنَا وَٱبۡعَثۡ فِيهِمۡ رَسُولٗا مِّنۡهُمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَيُزَكِّيهِمۡۖ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ﴾⟪2:129⟫ الآية (129) - سورة البقرة.\nالعزيز: الذي يقهر ولا ويقهر، وتعزر فلأن بفلان، والعزاز من الأرض ما فيه صلابة بازاء الذلول، وعز الشيء إذا قل اعتبارا بأن كل موجود مملوك، وكل مفقود مطلوب، والحكمة حدت بحدود على اعتبارات مختلفة، إما اعتبارا بمبدأها، فقد قيل: هي معرفة حقائق الأشياء، وقيل: معرفة الأشياء الإنسية والأشياء الإلهية، وهذا هو كالأول، إلا إنه أبين، وإما اعتبارا بمنتهاها، فقد قيل: هي إماتة الشهود وقلا الاكتراث بالموت المحمود، وقيل: الترشح بالعلم والعمل لإدراك ثواب الله- عز وجل-، فأما الرسول- الذي طلبه إبراهيم- عليه السلام، فقد روي عن نبينا - صلى الله عليه وسلم - أنه قال: \" أنا دعوة أبي إبراهيم وبشارة عيسى بن مريم \" يعني بالأول: قوله: ﴿وَٱبۡعَثۡ فِيهِمۡ رَسُولٗا مِّنۡهُمۡ﴾⟪2:129⟫، وبالآخر: قوله: ﴿وَمُبَشِّرَۢا بِرَسُولٖ يَأۡتِي مِنۢ بَعۡدِي ٱسۡمُهُۥٓ أَحۡمَدُۖ﴾⟪61:6⟫.\nإن قيل: كيف قال: يتلو عليهم آياتك ويعلمهم الكتاب والحكمة وليس الكتاب إلا الآيات، وما وجه هذا الترتيب؟\nقيل: أما الآيات فهي الآيات الدالة على معجزة النبي - صلى الله عليه وسلم - وذكر التلاوة لما كان أعظم دلالة نبوته متعلقا بالقرآن، وأما الترتيب فلأن أول منزلة النبي - صلى الله عليه وسلم - بعد ادعاء النبوة الإتيان بالآيات الدالة على نبوته، ثم بعده تعليمهم الكتاب، أي تعريفهم حقائقه لا ألفاظه فقط، ثم بتعليمهم الكتاب يوصلهم إلي\n⟦1:317⟧\nإفادة المحكمة وهي أشرف منزلة العلم، ولهذا قال: ﴿وَمَن يُؤۡتَ ٱلۡحِكۡمَةَ فَقَدۡ أُوتِيَ خَيۡرٗا كَثِيرٗاۗ﴾⟪2:269⟫، ثم بالتدرج في الحكمة يصير الإنسان مزكى.\n، أي مطهرا مستصلحا لمجاورة الله- عز وجل-."}, {"a": [130], "v": 1, "p": 317, "ev": 1, "ep": 318, "sid": 318, "t": "قوله - عز وجل -:\n﴿وَمَن يَرۡغَبُ عَن مِّلَّةِ إِبۡرَٰهِـۧمَ إِلَّا مَن سَفِهَ نَفۡسَهُۥۚ وَلَقَدِ ٱصۡطَفَيۡنَٰهُ فِي ٱلدُّنۡيَاۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ﴾⟪2:130⟫\nالآية (130) سورة البقرة.\nالرغبة: سعة الإرادة، ومنه بطل رغيب أي نهم، والرغيب الشيء المرغوب فيه، ومش عدى بعن اقتضى صرف الإرادة عن ذلك الشيء، وذلك بالزهد فيه، والاصطفاء تناول صفوة الشيء، كما أن الاختيار تناول خيره، والاجتباء تناول جانبه أي وسطه، وهو المختار، و (سفه نفسه) قيل: تقديره سفه، نفسه، وقيل: أصله سفه نفسه، فصرف الفعل عنه، نحو: بطر معيشته، وسفه نفسه أبلغ من جهلها، وذاك أن الجهل ضربان جهل بسيط، وهو أن لا يكون للإنسان اعتقاد في الشيء وجهل مركب، وهو أن\nيعتقد في الحق أنه باطل، وفي الباطل أنه حق، والسفه أن يعتمد ذلك، ويتحرى بالفعل مقتضاها ما اعتقده، فبين تعالى أن من رغب عن ملة إبراهيم، فإن ذلك لسفهه نفسه، وذلك أعظم مذمة، فهو مبدأ لكل نقيصة، وذاك أن من جهل نفسه جهل أنه مصنوع، وإذا جهل كونه مصنوعا جهل صانعه، وإذا لم يعلم أن له صانعا، فكيف يعرف أمره ونهيه، وما حسنه وقبحه، ولكون معرفتها ذريعة إلى معرفة الخالق- جد ثناؤه- قال: ﴿وَفِيٓ أَنفُسِكُمۡۚ أَفَلَا تُبۡصِرُونَ﴾⟪51:21⟫، وقال: ﴿وَلَا تَكُونُواْ كَٱلَّذِينَ نَسُواْ ٱللَّهَ فَأَنسَىٰهُمۡ أَنفُسَهُمۡۚ﴾⟪59:19⟫\nفإن قيل: كيف وصفه بالاصطفاء في الدنيا وبالصلاح في الآخرة، والنظر يتقضي عكس ذلك، فإن الصلاح وصف يرجع إلى الفعل، وذلك يكون في الدنيا، والاصطفاء حال يستحقه العبد بكونه صالحا، فحقه أن يكون في الآخرة؟ قيل الاصطفاء ضربان، أحدهما كما قلت والأخر في الدنيا، وهو اختصاص الله بعض العبيد بولايته ونبوته لخصوصيته فيه وهو المعنى بقوله\n⟦1:318⟧\n﴿شَاكِرٗا لِّأَنۡعُمِهِۚ ٱجۡتَبَىٰهُ﴾⟪16:121⟫، والصلاح وإن اعتبر بأحوال الدنيا، فمجارى به في الآخرة، فبين تعالى أنه مجتبى في الدنيا لما عرف الله من حكمته فيه، ومحكوم له في الآخرة بصلاحه في الدنيا تنبيها أن الثواب في الآخرة يستحقه باصطفائه في الدنيا، وإنما استحق لصلاحه فيها، وجوز أن يكون قوله \" في الآخرة \" أي في أفعال الآخرة لمن الصالحين، ويجوز إن عنى بقوله \" في الدنيا \" حال بقائه، و \" في الآخرة \" حال وفاته، ويكون الإشارة بصلاحه إلى الثناء الحسن عليه الذي رغب إلى الله تعالى فيه بقوله: ﴿وَٱجۡعَل لِّي لِسَانَ صِدۡقٖ فِي ٱلۡأٓخِرِينَ﴾⟪26:84⟫، ويجوز أنه لما كان الناس ثلاثة أضرب: مظالم، ومقتصد، وسابق غبر عن السابق بالصالح، فكل سابق إلى طاعة الله ورحمته صالح، وفي الجملة، فإن الصالح هو الخارج عن حد الرذيلة، وليس في الدنيا على الإطلاق بكل نظر صالح، بل عامة ما فيه يمكن أن يوصف بفاسد بها إما حالة ما أو بنظر ما، فإذن الصلاة المطلق في الآخرة، فلهذا خص بها .."}, {"a": [131], "v": 1, "p": 318, "ev": 1, "ep": 319, "sid": 319, "t": "قوله - عز وجل -:\n﴿إِذۡ قَالَ لَهُۥ رَبُّهُۥٓ أَسۡلِمۡۖ قَالَ أَسۡلَمۡتُ لِرَبِّ ٱلۡعَٰلَمِينَ﴾⟪2:131⟫ الآية (131) سورة البقرة.\nلما سأل الله تعالى بقوله: ﴿وَٱجۡعَلۡنَا مُسۡلِمَيۡنِ لَكَ﴾⟪2:128⟫، أجابه بقوله تعالى: \" أسلم \" أي أخلص سرك فإنه موضع الاطلاع، وإلى ذلك أشار النبي - صلى الله عليه وسلم - بقوله: \" أخلص يكفك القليل من العمل \"، وبقوله: \" الأعمال بالنيات \" وقوله تعالى: ﴿وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ﴾⟪98:5⟫، وقيل معنى \" أسلم \" استأسر لهم كقولك للأسير: استسلم، وقيل: معناه: اجعل نفسك مسلمة عن أسر الشيطان، حيث قال: ﴿وَلَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ ۝ إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِينَ﴾، وهذان القولان واحد في\n⟦1:319⟧\nالحقيقة فإن من أسره الرحمن فاستأسر له فهو الحر المطلق عن عبادة غيره، وقد قيل: \" لن تكون عبدا لله حقا حتى لا تكون لما دونه مسترقا \"، وإلى ذلك أشار بقوله: ﴿وَلَا يُشۡرِكۡ بِعِبَادَةِ رَبِّهِۦٓ أَحَدَۢا﴾⟪18:110⟫ وروي أن [إبراهيم عليه السلام] لما طلب الخلة من الله أوحى إليه فقال: (من طلبني أبليته)، فقال: إذا نلت الخلة لم أبال بالبلية، فلما أتى عليه حول قال: (من أحبني قتلته)، فقال: \" إذا انتهيت في الخلة لم أبال بقتل الدنيا \"، وقوله \" أسلمت \" مبني في المعنى على الأول وكأنه موعد منه أنه متأهب لما يراد منه، وقد حثنا الله تعالى علي الاقتداء به في الاستسلام له والاستفادة منه الشرف الكبير جزاء بذلك ..."}, {"a": [132], "v": 1, "p": 319, "ev": 1, "ep": 320, "sid": 320, "t": "قوله- عز وجل:\n﴿وَوَصَّىٰ بِهَآ إِبۡرَٰهِـۧمُ بَنِيهِ وَيَعۡقُوبُ يَٰبَنِيَّ إِنَّ ٱللَّهَ ٱصۡطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ﴾⟪2:132⟫\nالآية (132) - سورة البقرة.\nالوصية: التقدم إلى الغير بما يعمل به مقترنا بوعظ واشتقاقه من وصاه أي وصله، ومضاده قصاه أي فصله، وقوله: [بها] أي بالملة، وقيل بالكلمة التي دل عليها قوله: \" أسلمت \"، وكلاهما غير منفك من الآخر، إذ كانت هذه الكلمة من جملة الملة، والملة مقتضية لهذه الكلمة، فبين تعالى أن إبراهيم وصى بنيه، ووضع يعقوب بنيه أيضا بها كما أوصى إبراهيم، وقال: ﴿إِنَّ ٱللَّهَ ٱصۡطَفَىٰ لَكُمُ ٱلدِّينَ﴾⟪2:132⟫ أي دين إبراهيم، فحذف القول لتضمن الوصية لذلك، وحث على الإسلام، أي أسلموا قبل أن تموتوا، وليس ذلك نهيا عن الموت، وإنما هو حث على الإسلام المتقدم ذكره فهو الذي يفيد الحياة الأبدية المذكورة في قوله: ﴿وَلَا تَحۡسَبَنَّ ٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ أَمۡوَٰتَۢاۚ بَلۡ أَحۡيَآءٌ عِندَ رَبِّهِمۡ يُرۡزَقُونَ﴾⟪3:169⟫\n⟦1:320⟧"}, {"a": [133], "v": 1, "p": 320, "ev": 1, "ep": 321, "sid": 321, "t": "قوله - عز وجل -:\n﴿أَمۡ كُنتُمۡ شُهَدَآءَ إِذۡ حَضَرَ يَعۡقُوبَ ٱلۡمَوۡتُ إِذۡ قَالَ لِبَنِيهِ مَا تَعۡبُدُونَ مِنۢ بَعۡدِيۖ قَالُواْ نَعۡبُدُ إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ إِلَٰهٗا وَٰحِدٗا وَنَحۡنُ لَهُۥ مُسۡلِمُونَ﴾⟪2:133⟫ الآية (133) - سورة البقرة.\nالشهود: حضور بالذات أو بالعناية أو بالمقال، وأحضر الفرس [أصله] صار ذا حضور.\nوالفرق بين الإحضار والعدو أن الإحضار يقال اعتبارا بالمنتهى والعدو اعتبارا بالمبدأ المتجاوز لأنه من عداه إذا تجاوزه، وجعل الحضارة بإزاء البداوة في التعارف، والمحتضر لمن حضره الأجل، ولما ذكر إبراهيم وأن دينه الإسلام، وأن يعقوب اقتدى به، ودعا نبيه إليه، وقادهم على ذلك وأخذ اعترافهم بين أن مع وصيته لأولاده كان على جملة اعترافه معهم لم يعن بقوله: ﴿مَا تَعۡبُدُونَ مِنۢ بَعۡدِيۖ﴾⟪2:133⟫ العبادة المشروعة فقط، وإنما عنى جميع الأعمال، وكأنه دعاهم أن لايتحروا في أعمالهم غير وجه الله - عز وجل- ولم يخف عليهم الاشتغال بعبادة الأصنام، وإنما خاف أن تشغلهم دنياهم، ولهذا قيل: \" ما قطعك عن الله فهو طاغوت \"، ولهذا قال: ﴿وَٱجۡنُبۡنِي وَبَنِيَّ أَن نَّعۡبُدَ ٱلۡأَصۡنَامَ﴾⟪14:35⟫، أي نخدم ما دون الله، وهدا المعنى تحراه الشاعر بالعبادة:\nفتى ملك اللذات أن تعتبدنه\n....\nوما كل ذي ملك لهن بمالك\nفإن قيل : لما قال: ﴿نَعۡبُدُ إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ﴾⟪2:133⟫، وتكرير اللفظ يقتضي دارين، فالجواب عن ذلك من وجهين، أحدهما من حيث اللفظ، وهو أن المضاف إلى المضمر متى عطف على المضاف إليه لابد من إعادة المضمر إذ كان المضمر المحرور لا يصح العطف عليه، والثاني من حيث المعنى، وهو أن المعبود\nلما لم يمكن سبيل إلى الوصول إليه إلا بالنظر، فكان لدى واحد نظر، بينوا أن معبودنا هو الواحد الذي أثبته، وأثبته أباؤك، ثم بين بقوله، ﴿وَنَحۡنُ لَهُۥ﴾⟪2:133⟫ أنه واحد، وقد استدل بالآية من منع من مقاسمة الجد\n⟦1:321⟧\nبالأخوة، وأسقط الأخوة مع الجد كما يسقطون مع الأب، واستدل بها أيضا في أن العم يجري مجرى الأب في الولاية على مال الصغيرة وتزويجها، وفهم الجملة أن تسميتها بالأب ليس بمنكر، بل قد يسمى [كل] كبير من الأجانب أبا على أن الأعمام والأجداد إذا كانوا مع الأب فتسميتهم بالآباء أقرب، كتسمية الشمس مع القمر قمرين، وتسمية آل المهلب معه مهالبة ..."}, {"a": [134], "v": 1, "p": 321, "ev": 1, "ep": 322, "sid": 322, "t": "قوله - عز وجل -:\n﴿تِلۡكَ أُمَّةٞ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡـَٔلُونَ عَمَّا كَانُواْ يَعۡمَلُونَ﴾⟪2:134⟫\nالآية (134) سورة البقرة.\nالأمة في الأصل المقصود كالعمدة والعدة في كونهما معمودأ ومعذب، وسمي الجماعة أمة من حيث تأمها الفرق، وقيل للجبن أمة لكونه متضمنا لأمة ما وسمى الدين أمة لكون الجماعة عليه، وقوله: ﴿إِنَّ إِبۡرَٰهِيمَ كَانَ أُمَّةٗ﴾⟪16:120⟫ أي جمع في نفسه في الفضيلة ما لا يجتمع إلا في أمة، وبهذا المعنى ألم الشاعرفي قوله:\nوليس على الله بمستنكر\n....\nأن يجمع العالم في واحد\nوالكسب: اجتلاب النفع بالعمل، وإذا قيل في المضرة، فعلى طريق التشبيه، ولما بين الحجة عليهم وإنهم لم يخالفوا في الاقتداء بإبراهيم بين من بعد أن أعمالهم وأعمالكم متباينة لايثاب ولا يعاقب أحد بما كان من الآخر كقوله: ﴿وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ﴾، وليس معنى بقوله: ﴿وَلَا تُسۡـَٔلُونَ عَمَّا كَانُواْ يَعۡمَلُونَ﴾⟪2:134⟫ السؤال المجرد، فقل أخبر أنه يقول لعيسى بن مريم ﴿ءَأَنتَ قُلۡتَ لِلنَّاسِ ٱتَّخِذُونِي وَأُمِّيَ إِلَٰهَيۡنِ مِن دُونِ ٱللَّهِۖ﴾⟪5:116⟫ إنما يعني المؤاخذة بها.\n⟦1:322⟧"}, {"a": [135], "v": 1, "p": 322, "ev": 1, "ep": 322, "sid": 323, "t": "قوله - عز وجل -:\n﴿وَقَالُواْ كُونُواْ هُودًا أَوۡ نَصَٰرَىٰ تَهۡتَدُواْۗ قُلۡ بَلۡ مِلَّةَ إِبۡرَٰهِـۧمَ حَنِيفٗاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ﴾⟪2:135⟫\nالآية (135) - سورة البقرة.\nيعني أن اليهود قالوا: كونوا يهودا تهتدوا، وقال النصارى مثل ذلك، فأنزل الله تعالى على نبيه:\n﴿قُلۡ بَلۡ مِلَّةَ إِبۡرَٰهِـۧمَ حَنِيفٗاۖ﴾⟪2:135⟫ أي تتبع ملته المجمع على كونها هدى، وبين بقوله: ﴿وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ﴾⟪2:135⟫ أن كلتى الطائفتين قد أشركت، وأن إبراهيم كان حنيفا، وكان يقال في الجاهلية ولمن كان على دين إبراهيم حنيفا عليهم عن طريقتهم إلى طريقة غيرها، ثم سمى من اختتن أو حج البيت [حنيفآ] لمن كان ذلك من سنته."}, {"a": [136], "v": 1, "p": 322, "ev": 1, "ep": 323, "sid": 323, "t": "قوله - عز وجل -:\n﴿قُولُوٓاْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَآ أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِيَ ٱلنَّبِيُّونَ مِن رَّبِّهِمۡ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ﴾⟪2:136⟫\nالآية (136) - سورة البقرة.\nالسبط ولد الولد، وأصله من سبط أي امتد، كأنه امتداد للفروع، ومنه سبط الكفين، والساباط البناء الممتد بين الدارين، والسباطة ما مد من الكناسة، وما امتدمن الشعر، وسباط الحمى اعتبارا بتمدد المحموم وتمطيه،\nإن قيل: كيف ابتدأ بما أنزل إلينا مع كونه متأخرا عن كل ما أنزل الله، وقال: ﴿وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ﴾⟪2:136⟫ ولم ينزل إلى إسماعيل وإسحق كتاب، ولم قال: ﴿وَمَآ أُوتِيَ مُوسَىٰ وَعِيسَىٰ﴾⟪2:136⟫ فخصهما بالإيتاء دون الإنزال، وزكر النبيين، وقد تقدم ذكر بعضهم.\nقيل: أما الابتداء بما أنزل إلينا، فلأنه أول بالإضافة إلينا، فالناس بعد مجيء محمد - صلى الله عليه وسلم -، مدعوون إلى الإيمان بما أنزل عليه أولا جملة وتفصيلا، ولا يجب الإيمان بما أنزل من قبل إلا على سبيل الجملة دون التفصيل، وأما المنزل إلى إسماعيل ومن ذكر معه، فهو المنزل على إبراهيم، إذ هم داخلون تحت\n⟦1:323⟧\nشريعته، وذلك كقولك: ما أنزل على محمد - صلى الله عليه وسلم - والمسلمين، وأما قوله ﴿وَمَآ أُوتِيَ مُوسَىٰ﴾⟪2:136⟫ فهو على الاستئناف، وقوله: ﴿وَمَآ أُوتِيَ ٱلنَّبِيُّونَ﴾⟪2:136⟫ معطوف عليها وقوله: ﴿مِن رَّبِّهِمۡ﴾⟪2:136⟫ خبره، فكأنه لما اختلف فيما أنزل عليهما ، وادعى بعض أتباعهما عليهما ما لم ينزل إليهما بين تعالى أن ما أوتيا أي ما خصابه لا ما ادعى عليهما، وما أوتي النبيون جملة المذكورين وغير المذكورين من ربهم، أي منزل من ربهم، ثم قال: ﴿لَا نُفَرِّقُ بَيۡنَ أَحَدٖ﴾⟪2:136⟫، أي لا يكون بمنزلة اليهود الدين آمنوا ببعض وكفروا ببعض.\nإن قيل: لم قال: بين أحد منهم، ولفظ أحد وإن كان قد يعمم به في النفي فهو متناول للواحد، ولو قال بينهم لكان أوجز؟ قيل: لما كان القصد إلى أن نبين أن لا نفرق بين واحد واحد ذكر لفظ أحد فكأنه قال: لا نفرق بين أحد وجماعتهما أي لا يخرج واحد من حكمهم، فكان لفظا أحد أدل على المعنى المقصود، ثم بين بقوله: ﴿وَنَحۡنُ لَهُۥ مُسۡلِمُونَ﴾⟪2:136⟫ إنا مسلمون له إسلام إبراهيم عليه السلام .."}, {"a": [137], "v": 1, "p": 323, "ev": 1, "ep": 324, "sid": 324, "t": "قوله - عز وجل -:\n﴿فَإِنۡ ءَامَنُواْ بِمِثۡلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهۡتَدَواْۖ وَّإِن تَوَلَّوۡاْ فَإِنَّمَا هُمۡ فِي شِقَاقٖۖ فَسَيَكۡفِيكَهُمُ ٱللَّهُۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ﴾⟪2:137⟫\nالآية (137) - سورة البقرة.\nالشقاق المنازعة، يقال: شق العصا، أي فارق الجمع، وشاق القوم صار كل نفر في شق، وشاقوا الله أي صاروا في شق غير شق أوليائه، وعلى ذلك: ﴿يُحَآدُّونَ ٱللَّهَ﴾ أي صاروا في حد غير حده ..\nإن قيل: ة كيف قال: ﴿فَإِنۡ ءَامَنُواْ بِمِثۡلِ مَآ ءَامَنتُم بِهِۦ﴾⟪2:137⟫ ولم يقل أبما أمنتم أو ﴿بِمِثۡلِ مَآ ءَامَنتُم﴾⟪2:137⟫، وذلك يقتضي إثبات مثل الله- عز وجل-، وقد روي عن ابن عباس أنه قال: لا تقولوا: ﴿فَإِنۡ ءَامَنُواْ بِمِثۡلِ مَآ ءَامَنتُم بِهِۦ﴾⟪2:137⟫ [ويكن قولوا فإن أمنوا بالذي أمنتم به] وإن لم يكن هذا السؤال لازما فما كان [وجه] الإنكار منه؟ قيل إن الباء ههنا ليس للتعدية كما هو في قولك (مررت بزيد)، و (آمنت بالله) وإنما هو للإله، ومعناه أن تحروا الإيمان بالسبيل الذي تحريتم به، والإشارة بقوله: ﴿بِمِثۡلِ مَآ ءَامَنتُم بِهِۦ﴾⟪2:137⟫ إلى السبيل المذكور في قوله: ﴿قُلۡ هَٰذِهِۦ سَبِيلِيٓ أَدۡعُوٓاْ إِلَى ٱللَّهِۚ﴾⟪12:108⟫ وسبيل الله المتوصل به إليه ثلاث منازل\n⟦1:324⟧\nعلى القول المجمل مرتب بعضها على بعض الأول: معرفة الأحكام الظاهرة والعمل بها، والثاني: معرفة علم الزهاد من عيوب النفس وقمع الشهوات وأخذ النفس به، والثالث: علم المعاملات، وهي معرفة الخواطر ومراعاتها، وذلك السبيل إليه، ولا سبيل إلى تحصيل الإيمان الحقيقي الذي وصف به المؤمنين في قوله: ﴿إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ﴾⟪8:2⟫ إلا بها، وهذه المنازل الثلاث هي المعنية بقوله- عليه السلام- \" سائل العلماء، وخالط الحكماء، وجالس الكبراء \"، فبين تعالى أن من أمن سالكا هذا السبيل، فقد اهتدى، ومن جمع فقد شاق، ثم قال ﴿فَسَيَكۡفِيكَهُمُ ٱللَّهُۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ﴾⟪2:137⟫ تسكينا للمؤمنين وأمنا من معرفتهم ..."}, {"a": [138], "v": 1, "p": 324, "ev": 1, "ep": 325, "sid": 325, "t": "قوله - عز وجل -:\n﴿صِبۡغَةَ ٱللَّهِ وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ صِبۡغَةٗۖ وَنَحۡنُ لَهُۥ عَٰبِدُونَ﴾⟪2:138⟫\nالآية (138) - سورة البقرة.\nالصبغة إشارة من الله- عز وجل- إلى ما أوجده فينا من بداية العقول التي ميزنا بها من البهائم، رشحنا به لمعرفته ومعرفة حسن العدالة وطلب الحق وهو المشار إليه بالفطرة في قوله: ﴿فِطۡرَتَ ٱللَّهِ ٱلَّتِي فَطَرَ ٱلنَّاسَ عَلَيۡهَاۚ لَا تَبۡدِيلَ لِخَلۡقِ ٱللَّهِۚ﴾⟪30:30⟫ الآية ...\nوالمعنى بقوله- عليه السلام- \" كل مولود يولد على الفطرة \" الخير، وتسمية ذلك بالصبغة من حيث أن قوى الإنسان التي ركب عليها إذا اعتبرت بداية يجري مجرى الصبغة التي هي زينة للمصبوغ، ولما كانت اليهود والنصارى إذا لقنوا أولادهم اليهودية والنصرانية يقولون قد صبغناه بين تعالى أن الإيمان بمثل ما أمنتم به هو صبغة الله وفطرته التي ركزها في الخلق، ولا أحد أحسن\n⟦1:325⟧\nصبغة منه، وقوله: ﴿وَنَحۡنُ لَهُۥ عَٰبِدُونَ﴾⟪2:138⟫ تعريض بهم أي لا نشرك [به] كشرككم، وقول الحسن وقتادة ومجاهد أن الصبغة هي الدين، وقول غيرهم إنها الشريعة، وقول من قال هو الختان إشارة إلى مغزى واحد، وقد قيل: صبغة الله على مراتب أولها ما ركب فينا من الهداية وهي الفطرة والثانية: الهداية بالتوفيق، والثالثة: الهداية ببعثة الرسل، والرابعة: الهداية في الترقي توليه إلى الدرجة العليا والسعادة القصوى ..."}, {"a": [139], "v": 1, "p": 325, "ev": 1, "ep": 326, "sid": 326, "t": "قوله - عز وجل -:\n﴿قُلۡ أَتُحَآجُّونَنَا فِي ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمۡ وَلَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡ وَنَحۡنُ لَهُۥ مُخۡلِصُونَ﴾⟪2:139⟫\nالآية (139) - سورة البقرة.\nالمحاجة: المقاومة في إظهار الحجة البينة للحجة أي المقصد وقد ألزمهم بهذه الآية الحجة المذكورة في قوله: ﴿وَأَلۡزَمَهُمۡ كَلِمَةَ ٱلتَّقۡوَىٰ﴾⟪48:26⟫، ولما كانت الشرائع مبنية بالقول المجمل على ثلاثة أشياء ...\nالإقرار بالباري- عز وجل-، والعمل له والإخلاص في ذلك قال ..\nقل لهم إنا قد تشاركنا في الإقرار بالله- عز وجل- وفى العمل له ونحن قد حصل لنا الإخلاص [في ذلك] من دونكم،\nفإن قيل: ومن أين؟\nإن الإخلاص حصل للمسلمين دونهم، وهل هذا إلا مجرد ل الدعوى قيل قد أحالهم على التأمل، وذلك ظاهر بالاستقراء والتدبر، فإن الأصول الاعتقادية هي ما ذكر الله- عز وجل-، [في قوله] ﴿وَمَن يَكۡفُرۡ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ﴾⟪4:136⟫ وإذا تأمل حالة الإقرار بالله تعالي فقد أخلص المسلمون فيها يدعيه اليهود من التشبيه والنصارى من التثليث، وما ادعوه على جبريل أنه عدو لهم وما ادعاه اليهود على إبراهيم، حيث زعموا أنه لم يكن نبيا، وإنما كان رجلا صالحا، ونسبوا إليه لوطآ من الفجور ببنيه في حال سكره وادعى النصارى في نبوة عيس- عليه السلام- وإنكارهم بعض ما في التورط والإنجيل، وما ذكروه من البعث حيث قالوا ﴿لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامٗا مَّعۡدُودَةٗۚ﴾⟪2:80⟫ وادعت النصارى أنه لا بعث، وإنما ينال الثواب والعقاب الأرواح، فإذن قول المسلمين ﴿وَنَحۡنُ لَهُۥ مُخۡلِصُونَ﴾⟪2:139⟫ ظاهر ...\n⟦1:326⟧"}, {"a": [140], "v": 1, "p": 326, "ev": 1, "ep": 327, "sid": 327, "t": "قوله - عز وجل -:\n﴿أَمۡ تَقُولُونَ إِنَّ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطَ كَانُواْ هُودًا أَوۡ نَصَٰرَىٰۗ قُلۡ ءَأَنتُمۡ أَعۡلَمُ أَمِ ٱللَّهُۗ وَمَنۡ أَظۡلَمُ مِمَّن كَتَمَ شَهَٰدَةً عِندَهُۥ مِنَ ٱللَّهِۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ﴾⟪2:140⟫ الآية (140) سورة البقرة.\nقوله: ﴿أَمۡ تَقُولُونَ﴾⟪2:140⟫ معطوف على قوله (أتحاجوننا) - أم تدعون أن الأنبياء كانوا على دينكم تنبيها أنه من المحال أن يكون المتقدم مقتديا بالمتآخر ومستند بسنته، ومن قرأ بالياء فوجه العدول فيه من الخطاب إلى الإخبار استجهالا لهم بما كان منهم من هذه الدعوة كما يفعل العالم من الإعراض عمن يخاطبه بعد ارتكابه جهالة شنيعة إلى غيره، واحتج عليهم بمقدمتين فقال: أنتم أعلم أم الله أي قد بينت أن الله أعلم منكم، وبينت أنه ليس بغافل عما تعملون وقد كتمتم الشهادة عنها، ومن كتم من الله شهادة عنده مع كون الله بهذا الوصف فهو أظلم الخلائق، فهدا تبكيت لهم في كتمانهم أحوال النبي- عليه السلام- وسائر الأنبياء واحتج عليهم بما لا انفصال لهم عنه، وقوله: ﴿مِنَ ٱللَّهِۗ﴾⟪2:140⟫ على هذا متعلق بقوله:، ﴿كَتَمَ﴾⟪2:140⟫ وقيل؟ إنه متعلق بقوله شهادة، أي من كتم عن الناس شهادة مصدرها من الله - عز وجل، وقيل: في الآية قول أخر، وهو أن قوله: ﴿مِنَ ٱللَّهِۗ﴾⟪2:140⟫ يتعلق بقوله \" أظلم \" وقوله ﴿مِمَّن كَتَمَ﴾⟪2:140⟫ من جمله الذين كتموا وتقدير هذا التأويل قد ثبت أن الله - عز وجل- أعلم منكم، وقد حكم أن الشهادة كتمانها عصيان بقوله: ﴿وَمَن يَكۡتُمۡهَا فَإِنَّهُۥٓ ءَاثِمٞ قَلۡبُهُۥۗ﴾⟪2:283⟫ فكأنه قيل: من أظلم من الله من الذين كتموا الشهادة إن كان الأمر على ما ذكرتم ولم يخبركم،.\nوهذا كقولك: من أظلم ممن يجور على الفقير من السلطان أي لا أحد أظلم منه إدا ظلمه، وعلى هذا يكون قوله: ﴿وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ﴾⟪2:140⟫ على سبيل التهديد لهم.\n⟦1:327⟧"}, {"a": [141], "v": 1, "p": 327, "ev": 1, "ep": 327, "sid": 328, "t": "قوله - عز وجل -:\n﴿تِلۡكَ أُمَّةٞ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡـَٔلُونَ عَمَّا كَانُواْ يَعۡمَلُونَ﴾⟪2:141⟫\nالآية (141) - سورة البقرة.\nأعادت هذه الآية من أجل أن العادة مستحكمه في الناس صالحهم وطالحهم أن يفتخروا بآبائهم ويقتدوا بهم في متحرياتهم سيما في أمور دينهم، ولهذا حكى عن الكفار قولهم: ﴿إِنَّا وَجَدۡنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٖ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّقۡتَدُونَ﴾⟪43:23⟫، فأكد الله تعالى القول في إنزالهم عن هذه الطريقة، وذكر في أثر ما حكى من وصية إبراهيم ويعقوب ببنيه بذلك تنبيها أن الأمر سواء على ما قلت أو لم يكن، فليس لكم ثواب فعلهم ولا عليكم عقابه، وفي الثاني لا ذكر ادعاءهم اليهودية والنصرانية لآبائهم أعاد أيضا تأكيدا عليهم تنبيها على نحو ما قال: ﴿وَكُلَّ إِنسَٰنٍ أَلۡزَمۡنَٰهُ طَٰٓئِرَهُۥ فِي عُنُقِهِۦۖ﴾⟪17:13⟫، وقوله: ﴿لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ﴾⟪2:286⟫، وقوله: ﴿وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ﴾، ولما جرت به عادتهم، تقررت به معرفتهم كل شاة تناط برجليها."}, {"a": [142], "v": 1, "p": 327, "ev": 1, "ep": 328, "sid": 328, "t": "قوله - عز وجل -:\n﴿سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمۡ عَن قِبۡلَتِهِمُ ٱلَّتِي كَانُواْ عَلَيۡهَاۚ قُل لِّلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ﴾⟪2:142⟫\nالآية (142) سورة البقرة.\nالسفيه كل معتقد باطلا يسرع إلى إظهار معتقده، ولا يكون له ثبات، والقبلة وإن كانت في الأصل اسما للحال التي عليها الإنسان من الاستقبال كالجلسة والقعدة، فقد صار في التعارف للمكان المتوجه نحوه للصلاة، وهؤلاء السفهاء المنكرون لتغيير القبلة اليهود على ما رد عن ابن\n⟦1:328⟧\nعباس، ومشركو العرب عن الحسن، والمنافقون عن السدي، ولا تنافي بين أقوالهم، فكل قد عابوا وكل سفهاء، وقد روي أن بعضهم قال: لا يثبت محمد على دين، وبعضه قال: \" رجع إلى قبلة قومه، وسيراجع إلى دينهم، وروي أن قوما من اليهود أتوه وقالوا: ما ولاك عن قبلتنا؟ ارجع إليها نتبعك فأنزل الله تعالى ذلك تبيينا أن الأمكنة متساوية عند الله، فله المشرق والمغرب، وهو الهادي إلي الطريق المستقيم فأي وجه يتوجه إليه، فهو تعالى موجود كما قال ﴿فَأَيۡنَمَا تُوَلُّواْ فَثَمَّ وَجۡهُ ٱللَّهِۚ﴾⟪2:115⟫، وكقوله: ﴿وَهُوَ ٱلَّذِي فِي ٱلسَّمَآءِ إِلَٰهٞ وَفِي ٱلۡأَرۡضِ إِلَٰهٞۚ﴾⟪43:84⟫ في اعتبار به والارتسام لأوامره لا بالأمكنة والجهات المختلفة ..."}, {"a": [143], "v": 1, "p": 328, "ev": 1, "ep": 334, "sid": 329, "t": "قوله- عز وجل:\n﴿وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا لِّتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيۡكُمۡ شَهِيدٗاۗ وَمَا جَعَلۡنَا ٱلۡقِبۡلَةَ ٱلَّتِي كُنتَ عَلَيۡهَآ إِلَّا لِنَعۡلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيۡهِۚ وَإِن كَانَتۡ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُۗ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمۡۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٞ رَّحِيمٞ﴾⟪2:143⟫\nالآية (143) - سورة البقرة.\nالوسط في الأصل اسم للمكان الذي يستوي إليه المساحة من الجوانب في المدورة، ومن الطرفين في المطول كالنقطة من الدائرة ولسان الميزان من العمود، ويجعل عبارة عن العدل، وكذلك السواء والنصف.\n، وشبه به كل ما وقع بين طرفين إفراط وتفريط كالجود بين السرف والبخل والشجاعة\n⟦1:329⟧\nبين التهور والجبن، ثم جعل عبارة عن المختار من كل شيء حتى قيل: فلان من أوسطهم نسبيا، وكما جعلهم وسطا جعلهم خيرا في قوله: ﴿كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ﴾⟪3:110⟫ والعقب مؤخر القدم، فتصور مكانه من الحيوان تارة، فاعتبرت في قولهم: يعقبه واعتقبه نحو: استدبره، وقفاه، وعاقب الليل النهار، وقيل المعقبات للملائكة التي تتعاقب في الليل والنهار والعقوبة منه، والعقبة الجبل اعتبارا بالصاعد الذي يميل [نحو عقبة] في ممره، ولما كان يؤخذ العقب من بعض الحيوانات فيشد به، قالوا: عقبته: أي شددته بالعقب نحو دسته وانقلب على عقبيه إذا رجع عائدا نحو: ارتدا على آثارهما، ورجع عوده على بدئه.\nإن قيل: كيف جعلهم وسطا؟ الخلق أم لخلق خصهم به؟ أم لعلم ركزه فيهم؟ أم لشرع شرعه لهم؟.\nقيل: قد خصهم بكل ذلك، والظاهر من ذلك هي الشريعة التي إدا اعتبرت بسائر الشرائع وجد لها حد الاعتدال، وهو أن بني إسرائيل لما عتوا كما حكى الله عنهم في غير موضع شدد عليهم أشياء صارت عليهم إصرا وأغلالا، نحو: ﴿وَمِنَ ٱلۡبَقَرِ وَٱلۡغَنَمِ حَرَّمۡنَا عَلَيۡهِمۡ شُحُومَهُمَآ إِلَّا مَا حَمَلَتۡ ظُهُورُهُمَآ أَوِ ٱلۡحَوَايَآ أَوۡ مَا ٱخۡتَلَطَ بِعَظۡمٖۚ﴾⟪6:146⟫، ولذلك أمرنا تعالى فيما يدعونه أن نقول ﴿وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ﴾⟪2:286⟫، ثم خفف عنهم على لسان عيسى بعض التخفيف، ولهذا حكى عنهم: ﴿وَلِأُحِلَّ لَكُم بَعۡضَ ٱلَّذِي حُرِّمَ عَلَيۡكُمۡۚ﴾⟪3:50⟫، وتمم ذلك بمحمد - صلى الله عليه وسلم - فقال: ﴿ٱلَّذِينَ يَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِيَّ ٱلۡأُمِّيَّ ٱلَّذِي يَجِدُونَهُۥ مَكۡتُوبًا عِندَهُمۡ فِي ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِيلِ﴾⟪7:157⟫ إلى قوله: ﴿وَيُحِلُّ لَهُمُ ٱلطَّيِّبَٰتِ وَيُحَرِّمُ عَلَيۡهِمُ ٱلۡخَبَٰٓئِثَ﴾⟪7:157⟫ وقال: ﴿مَا يُرِيدُ ٱللَّهُ لِيَجۡعَلَ عَلَيۡكُم مِّنۡ حَرَجٖ﴾⟪5:6⟫، وقال عليه السلام \" بعثت بالحنيفية السهلة \"، فصارت شريعته متوسطة بين الإفراط الذي هو الإصر والأغلال وبين التفريط الذي هو\n⟦1:330⟧\nالإضاعة والإهمال، وعلى ذلك قال ﴿كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ﴾⟪3:110⟫، ولكون هذه الشريعة وسطا\nسمى مقتضاهما كلمة (سواء) أي عدلا باتفاق العقول فقال: ﴿قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ تَعَالَوۡاْ إِلَىٰ كَلِمَةٖ سَوَآءِۭ﴾⟪3:64⟫ الآية ..\nإن قيل: هل ذلك للأمة كلهم أم للبعض دون البعض؟ قيل: الخطاب لأصحاب النبي - صلى الله عليه وسلم - خاصة على وجه، وهو خطاب للكافة عامة على وجه، وذلك أن أصحابه في الحقيقة صاروا موجودين خير الناس، وسائر أمته ممكنون أن يصيروا أخيارا وذلك بقبولهم الفيض الذي أباحه الله لهم بعقولهم ولسان نبيهم وتدرجهم إلى بلوغ أقاصيه ..\nإن قيل: على أي وجه شهادة النبي - صلى الله عليه وسلم - علي الأمة وشهادة الأمة على الناس؟ قيل: الشاهد هو العالم بالشيء المخبر عنه مبينا، حكمه، وأعظم شاهد من ثبتت شهادته بحجة، ولما خص الله تعالى الإنسان بالعقل والتمييز بين الخير والشر وكمله ببعثة الأنبياء، وخص هذه الأمة بأتم كتاب، كما وصفه بقوله: ﴿مَّا فَرَّطۡنَا فِي ٱلۡكِتَٰبِ مِن شَيۡءٖۚ﴾⟪6:38⟫ وقوله: ﴿وَنَزَّلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ تِبۡيَٰنٗا لِّكُلِّ شَيۡءٖ﴾⟪16:89⟫، فأفادناه- عليه السلام- وبينه لنا صار حجة وشاهدا أن نقول ما جاءنا من بشير ولا نذير، وجعل أمته المتخصصة بمعرفته شهودا على سائر الناس ...\nإن قيل: هل أمته شهود كلهم؟ أم بعضهم؟\nقيل: كلهم ممكنون من أن يكونوا شهداء وذلك بشريطة أن يزكوا أنفسهم بالعلم والعمل الصالح، فمن لم يزك نفسه لم ليكن شاهدا مقبولا، ولذلك قال تعالى: ﴿قَدۡ أَفۡلَحَ مَن زَكَّىٰهَا﴾⟪91:9⟫، وعلى هذا قال: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ بِٱلۡقِسۡطِ شُهَدَآءَ لِلَّهِ وَلَوۡ عَلَىٰٓ أَنفُسِكُمۡ﴾⟪4:135⟫، فالقيام بالقسط\n⟦1:331⟧\nمراعاة العدالة، وهي بالقول المجمل ثلاث:\nعدالة بين الإنسان ونفسه، وعدالة بينه وبين الناس، وعدالة بينه وبين الله- عز وجل-، فمن رعى\nذلك فقد صار عدلا شاهدا لله- عز وجل-.\nإن قيل: فهل هم شهود على بعض الأمم أم على الناس كافة؟ قيل بل كل شاهد على نفسه وعلى أمته وعلى الناس كافة فإن من عرف حكمة الله تعالي وجوده وعدله ورأفته، علم أن لم يغفل تعالى عنه ولا عن أحد من الناس، ولا يبخل عليهم ولا يظلمهم، ومن علم ذلك فهو شاهد لله على أن من زمانه وعلى من قبله ومن بعده، وعلى هذا الوجه ما روي في الخبر \" أن هذه الأمة تشهد للأنبياء على الأمم \"،\nإن قيل: ما المشبه وما المشبه به في قوله كذلك قيل: ولما قال: ﴿وَيَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ﴾⟪10:25⟫ بين أن نعمته بهذا التشريف كنعمته بالهداية إلى صراط مستقيم.\nقوله - عز وجل -:\n﴿وَمَا جَعَلۡنَا ٱلۡقِبۡلَةَ ٱلَّتِي كُنتَ عَلَيۡهَآ﴾⟪2:143⟫\nالآية (143) - سورة البقرة.\nيعني ما أمرناك بالتوجه إلى بيت المقدس إلا لنعلم، أي لنعلم الآن من يتبع الرسول ممن لا يتبعه، وقيل معناه: إلا لنعلم حينئذ من ينقاد لك من العرب في اتباعك إلى الصلاة إلى بيت المقدس، وقيل معناه: ما غيرنا حكم القبلة التي كنت عليها إلا لنعلم، والقبلة على هذا كله بيت القدس، وقيل معناه: ما جعلنا هذه القبلة التي أنت عليها أي أمرناك بها يعني الكعبة، وإنما استعمل فيه \" كان \" إشارة إلى أن حكم الله تعالى بدلك قد تقدم في سابق علمه، وقيل: عنى الكعبة حتى توجه إليها قبل\n⟦1:332⟧\nوروده المدينة، وهذا أظهر، فالآية التي بعدها هي الناسخة لا استفتح بقوله: ﴿قَدۡ نَرَىٰ﴾⟪2:144⟫ ..\nإن قيل: ما وجه قوله: ﴿إِلَّا لِنَعۡلَمَ﴾⟪2:143⟫، وذلك يقتضي استفادة علم وقد علم أن الله تعالى لم يزل عالما بما كان، وبما يكون؟ قيل إن ذلك من الألفاظ التي لولا السمع لما تجاسرنا على إطلاقها عليه تعالى، ومجاز ذلك على أوجه ..\nالأول: أن اللام في مثل ذلك تقتضي شيئين: حدوث الفعل في نفسه، وحدوث العلم به، ولما كان\nعلم الله لم يزل ولا يزال صار اللام فيه مقتضيا حدوث الفعل لا حدوث العلم.\nوالثاني: أن العلم يتعلق بالشيء على هو به، والله تعالى علمهم قبل أن يتبعوه غير تابعين،\nوبعد أن تبعوه علمهم تابعين، وهذا الجواب كالأول في الحقيقة، لأن التغيير داخل في المعلوم لا في\nالعلم.\nوالثالث ة معناه لنعلم حزبنا، فنسب ذلك إلى نفسه على علاته في نسبه، أفعال أوليائه إلى نفسه، كقوله تعالى: ﴿ٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا﴾⟪39:42⟫، وقال في موضع أخر: ﴿قُلۡ يَتَوَفَّىٰكُم مَّلَكُ ٱلۡمَوۡتِ ٱلَّذِي وُكِّلَ بِكُمۡ﴾⟪32:11⟫ وقال تعالى: ﴿وَعَلَّمَكَ مَا لَمۡ تَكُن تَعۡلَمُۚ﴾⟪4:113⟫ وإنما علمه بملائكته.\nوالرابع: معناه لنجازي، وذلك متعارف نحو: قولك: سأعلم.\nحسن بلائك، أي سأجازيك على حسب مقتضى علمي- قيل: فعبر عن الجزاء بالعلم لما كان هو سببه.\nوالخامس: أن عادة الحكيم إذا أفاد غيره علما أن يقول وتعالى \" حتى يعلم كذا \"، وإنما يريد إعلام المخاطب لكن يحل نفسه محل المشارك للمتعلم على سبيل اللطف ...\nإن قيل: كيف يتصور حقيقة انقلاب الإنسان على عقبيه؟\n⟦1:333⟧\nقيل: يتصور ذلك على وجهين: أحدهما: اعتبار لحال الإنسان ومعارفه، وهو أن الإنسان شرع في الفضيلة واكتساب المعرفة درجة درجة إلى حين الكمال، فإن حكمه في بطن أمه حكم النبات، ثم يصير في حكم الحيوان، ثم يصير بعد الولادة في حيز الإنسان باكتساب المعارف أولا فأول، ثم لا يزال يترقى بالعلم والعمل حتى ربما يصير قريبا من الملائكة علما وفضلا وعملا، ومتى أخل بمرتبته، وصل إليها، فرجع عنها فقد انقلب على عقبيه، والوجه الثاني: أن يعتبر الأديان وفضائلها، وذلك أن الله تعالى أنشأ الأديان، فمازال يتممها شيئا فشيئا إلى أن كملها بالنبي - صلى الله عليه وسلم - كما قال تعالى: ﴿ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ﴾⟪5:3⟫، وكما قال النبي عليه السلام في الخبر الذي قال فيه: ( ..\nفكنت في موضع اللبنة)، فمن أنعم عليه بأن أوجده بعد بعثته (عليه السلام) فرغب عن شريعته مائلا إلى غيرها من الشرائع المنسوخة قد انقلب على عقبيه، وبين بقوله: ﴿وَإِن كَانَتۡ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُۗ﴾⟪2:143⟫ أن الانتقال عن المألوف من القبلة مستصعب على الطبع، والإنسان ألوف لما يتعوده سيما الشريعة، فإن ذلك إنما لا ينقل عليه من أنعم الله عليه وهداه وعرف حكمته، وعلم أنه تعالى يأمر عباده بما هو أصلح لهم كأهل \" منا \" الذين لما أتاهم الخبر بنسب القبلة، وكانوا في الصلاة حولوا وجوههم نحو الكعبة من غير أن يستبينوا، وقوله: ﴿وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمۡۚ﴾⟪2:143⟫ هو تسكين لمن صلى إلي بيت المقدس، من المسلمين ومن أهل الكتاب قبل النسخ، وبين أنهم يثابون على ذلك، فقد\nروي أن قوما قالوا: كيف بمن مات من إخواننا وقد وصلوا إلى بيت القدس؟ فأنزل الله تعالى، ذلك،\nفإن قيل ولم قال؟ ﴿لِيُضِيعَ إِيمَٰنَكُمۡۚ﴾⟪2:143⟫ ولم يقل صلواتكم؟\n⟦1:334⟧\nقيل: عدل إلى لفظ الإيمان ألذي هو عام في الصلاة وغيرها ليفيدهم أنه لم يضع لهم شي مما عملوا به ثم نسخ عنهم ،\nفإن قيل: ولم لم يقل إيمانهم؟ قيل: ذكر بلفظ الخطاب ليتناول الماضين والباقين تغليبا لحكم المخاطب على الغائب في اللفظ، ثم بين بقوله تعالى: ﴿إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٞ رَّحِيمٞ﴾⟪2:143⟫ أنه لا يضيع إحسانهم وهو رؤوف بهم، فإن رأفته بالناس وإضاعة إحسانهم متنافيان لا يجتمعان."}, {"a": [144], "v": 1, "p": 334, "ev": 1, "ep": 336, "sid": 335, "t": "قوله عز وجل:\n﴿قَدۡ نَرَىٰ تَقَلُّبَ وَجۡهِكَ فِي ٱلسَّمَآءِۖ فَلَنُوَلِّيَنَّكَ قِبۡلَةٗ تَرۡضَىٰهَاۚ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥۗ وَإِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ لَيَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا يَعۡمَلُونَ﴾⟪2:144⟫ الآية: (144) سورة البقرة،\nقطر وشطر وشطن ألفاظ متقاربة المعاني تقارب ألفاظها، فقطر معناه انفصل عن قطره أي بجانبه ومنه القطرة القليل المنفصل من المانع، وشطر: انفصل وتباعد، ودار شطور منفصلة عن الدور، وشطون بعيدة، وقد يستعمل الشطور موضع الشطون لكن الشطون لما هو أبعد، ورجل شاطر أي منفصل عن الجماعة بالخلاعة، وشاطرته: أي أخذت شطرا وتركت له شطرا، وشاة شطور لها ضرع واحد وأحد ضرعيها أكبر كأنه لا يعتد بالآخر، وتوجهت شطره أي نحوه اعتبارا بالشطر المقابل من شطريه، وتقلب الوجه أبلغ من تقلب العين، على أن الوجه يراد به التوجه كقولك: \" وجهتي إلى فلان \"\nإن قيل: هل كان يستخط - عليه السلام - توجهه إلى بيت المقدس حتى قيل ﴿فَلَنُوَلِّيَنَّكَ قِبۡلَةٗ تَرۡضَىٰهَاۚ﴾⟪2:144⟫؟\nقيل لم يقصد بذلك أنك كنت ساخطة، وإنما كان - عليه السلام - يحركه السر، ويعلم بما يلقى في روعه أن الله تعالى يريد تغييرا في القبلة، وكان يتشوفه ويحثه، وقيل معنى (ترضاها) أي يرضاها، لكن يبين بهذا القول أن مرادك لم يخالف مرادي.\nوقول مجاهد وابن زيد، أحب النبي عليه السلام التوجه إلى الكعبة مخالفة لليهود وقول ابن عباس فإنه أحبها اقتداء بإبراهيم عليه السلام وقول الزجاج إنه أحبها لاستدعاء العرب بها إلى الإسلام فكلها صحيحة إذ لا منافاة بين هذه الإرادات، وهذه منزلة يشير إليها أولو الحقائق ويذكرون\n⟦1:335⟧\nأنها فوق التوكل، لأن قاضية المتوكل الاستسلام لما يجري عليه من القضاء كأعمى يقوده بصير فهو به، وهذه المنزلة هي أن يحرك الحق سره بما يريده فعله، وربما يكون ذلك بوحي من خارج لقوله، تعالى لإبراهيم أسلم، وربما كان ذلك بإلهام من باطن كما أوحى إلى أم موسى، ومعنى ﴿تَقَلُّبَ وَجۡهِكَ فِي ٱلسَّمَآءِۖ﴾⟪2:144⟫ أي تطلعك الوحي المنزل، وقيل: إن في ذلك تنبيها على حسن أدبه حينما انتظر ولده يسأل، فالولي الذي حصلت له القربة قد ينقص عن المسألة اتكالا على ما تيسر له، كما روي عنه عليه السلام أنه قال أن الله تعالى يقول:\n(من شغله ذكري عن مسألتي أعطيته أفضل من ما أعطى السائلين)\n....\nوعلى ذلك أول أمية بن أبي الصلت:\nإذا أثنى عليك المرء يوما ...\nكفاه من تعرضك الثناء\nوبين تعالى بهذه الآية رغبة النبي عليه السلام في التوجه إلى الكعبة وإلحائه، وقرن به علم أهل الكتاب بأن ذلك حق من الله- عز وجل- ونبه بقوله: ﴿وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ﴾ على وعيد لهم.\nووعد المؤمنين في إلحائهم وإمتناعهم ...\nإن قيل: من أين علم أهل الكتاب أن ذلك حق؟\nقيل: لما تضمن كتبهم من ذكر النبي- عليه السلام-، وعلمهم أن عبادة الله أن يخص كل رسول من أولى العزم بقبلة غير قبلة من تقدمه أنفا ...\nإن قيل: كيف خاطبه أولا بقولها ﴿فَوَلِّ وَجۡهَكَ﴾⟪2:144⟫ ثم عم بقولها: ﴿فَوَلُّواْ وُجُوهَكُمۡ﴾⟪2:144⟫، قيل: أما خطابه الخاص أولا، فتشريفا له، وإيجابا لرغبته وإنجازا لوعده، وأما خطابه العام بعده، فلأنه، كان\n⟦1:336⟧\nيجوز أن يعتقد أن هذا أمر قد خص عليه السلام به كما خص بقوله: ﴿قُمِ ٱلَّيۡلَ إِلَّا قَلِيلٗا﴾⟪73:2⟫، ولأنه لما كان تحويل القبلة أمرا له خطر خصهم بخطاب مفرد ليكون ذلك أبلغ، فمعلوم من السلطان إذا خاطب واليا من قبله بأمر ذي بال يعمه، ورغبته أن يخصه بخطاب مفرد ليكون ذلك أوقع عندهم [وأدعى لهم إلى قبولهم]، وليكون لهم في ذلك تشريف، ولأن في الخطاب العام تعليق حكم أخر به، وهو أنه لا فرق بين القريب والبعيد في وجوب التوجه (إلى الكعبة)، والضمير في قوله ﴿أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۗ﴾⟪2:144⟫ قيل هو التحويل قيل : هو التوجه، والقولان في التحقيق واحد."}, {"a": [145], "v": 1, "p": 336, "ev": 1, "ep": 337, "sid": 337, "t": "قوله عز وجل:\n﴿وَلَئِنۡ أَتَيۡتَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ بِكُلِّ ءَايَةٖ مَّا تَبِعُواْ قِبۡلَتَكَۚ وَمَآ أَنتَ بِتَابِعٖ قِبۡلَتَهُمۡۚ وَمَا بَعۡضُهُم بِتَابِعٖ قِبۡلَةَ بَعۡضٖۚ وَلَئِنِ ٱتَّبَعۡتَ أَهۡوَآءَهُم مِّنۢ بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ إِنَّكَ إِذٗا لَّمِنَ ٱلظَّٰلِمِينَ﴾⟪2:145⟫ الآية: (145) - سورو البقرة.\nإن قيل؟ كيف حكم، بأنهم لا يتبعون قبلتك وقد أمن منهم فريق- قيل: قال بعضهم: إن هذا حكم على الكل دون الأبعاض، وهذا صحيح بدلالة أنك لو قلت: ما أمنوا، ولكن آمن بعضهم لم يكن منافيا، وقيل عنى به وأقوام مخصوصون وقيل: عنى ما تبعوا قبلتك بقلوبهم، وقوله: (يوما أنت بتابع قبلتهم)، أي لا يكون ذلك منك، فمحال أن من عرف الله حق معرفته يرتد، وقد قيل: (ما رجع من يرجع إلا من الطريق)، أي: \" ما أخل بالإيمان إلا من لم يصل إليه حق الوصول \" ...\nإن قيل: فقد يوجد من يحصل له معرفة ثم يرتد؟ قيل: إن الذي يقدر أنه معرفة، وهو ظن متصور بصورة العلم، فأما أن يتحصل العلم الحقيقي ثم يعقبه الارتداد فمحال ولم يعن بهذه المعرفة\n⟦1:337⟧\nما جعله الله تعالي للإنسان بالفطرة، فإن ذلك كشررة تخمد إذا لم تتوقد، وبين أن بعضهم لا يتبع قبله البعض، وذلك لارتكابهم الهوى وتأنيهم عن تأمل الهدى، وحذر نبأ عن اتباع أهوائهم، ونبه أن اتباع الهوى بعد التحقق بالعلم يدخل متحريه في جملة الظلمة، وقد أكثر الله تحذيره من الجنوح إلى الهوى حتى كرر ذلك في عدة تواضع، وقول من قال الخطاب للنبي - صلى الله عليه وسلم - والمعني به الأمة، فلا معني لتخصصه، فإن الله تعالى يحذر نبيه من اتباع الهوى أكثر مما يحذر غيره المنزلة الرفيعة إلى تحديد الإنذار عليه أحوج حفظا لمتركته وصيانة لمكانته، وقد قيل: حق المرأة المجلوة أن يكون بعدها أكثر إذا كان القليل من الصدأ عليها أظهر ..\nإن قيل: كيف أجاب فقال: ﴿وَلَئِنۡ أَتَيۡتَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ بِكُلِّ ءَايَةٖ مَّا تَبِعُواْ قِبۡلَتَكَۚ﴾⟪2:145⟫، ولايقال إن جئتني ما فعلت، وإنما يقال: لم أفعل؟ قيل : قد قال سيبويه: إن ذلك لما تضمن معنى القسم، فأدخل على أن اللام صار جوابه كجواب القسم، وعلى ذلك قوله تعالى: ﴿وَلَئِنۡ أَرۡسَلۡنَا رِيحٗا فَرَأَوۡهُ مُصۡفَرّٗا لَّظَلُّواْ﴾⟪30:51⟫ وقال الأخفش: لما كان إن،) وهو متضمنان الشرط حمل \" إن \"، عدى \" لو \" فعلى هذا يصح أن يقال \" إن أتيتني ما أكرمتك \"، وعلى قول \" سيبوية \" لا يصح ما لم يكن مع \" إن \" اللام نحو للئن."}, {"a": [146], "v": 1, "p": 337, "ev": 1, "ep": 338, "sid": 338, "t": "قوله - عز وجل -:\n﴿ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡرِفُونَهُۥ كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمۡۖ وَإِنَّ فَرِيقٗا مِّنۡهُمۡ لَيَكۡتُمُونَ ٱلۡحَقَّ وَهُمۡ يَعۡلَمُونَ﴾⟪2:146⟫\nالآية (146) - سورة البقرة.\nأتيناهم أبلغ من قوله: (أوتوا)، فإن (أوتوا) قد يستعمل فيمن لم يكن له قبول، وأتيناهم أكثر ما جاء فيمن له قبول نحو: ﴿أُوْلَٰٓئِكَ ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَۚ﴾⟪6:89⟫، وعلى ذلك كل مما جاء من نحو هذا فيما يختص بإكرام نحو: ﴿هَدَيۡنَا وَٱجۡتَبَيۡنَآۚ﴾⟪19:58⟫، وقوله (يعرفونه) أي العلم الذي هو النبوة\n⟦1:338⟧\nالمتقدم ذكرها في قوله ﴿مِّنۢ بَعۡدِ مَا جَآءَكَ مِنَ ٱلۡعِلۡمِ﴾⟪2:145⟫ وقيل، عنى النبي عليه السلام بقوله: ﴿يَجِدُونَهُۥ مَكۡتُوبًا عِندَهُمۡ﴾⟪7:157⟫ وقيل: يعرفون أن التوجه إلى الكعبة حق واختلاف أقاويلهم باختلاف نظراتهم إلى الألفاظ من حيث المعنى بأن معرفة الرسول عليه السلام ومعرفة صدق قوله وصحة ما يأمر به من أمر القبلة متلازمة، وإنما قال: ﴿كَمَا يَعۡرِفُونَ أَبۡنَآءَهُمۡۖ﴾⟪2:146⟫ ولم يقل أنفسهم، لأن الإنسان لا\nيعرف نفسه إلا بعد انقضاء برهة من دهره، ويعرف ولده من حين وجوده، ثم في ذكر الابن، ما ليس في ذكر النفس، فإن الإنسان عصارة ذاته ونسخة صورته، وإنما قال: ﴿لَيَكۡتُمُونَ ٱلۡحَقَّ﴾⟪2:146⟫ ولم يقل يكتمونه، لأن في كتمان أمره كتمانه الحق جملة، وزاد في ذمهم بقوله: ﴿وَهُمۡ يَعۡلَمُونَ﴾⟪2:146⟫.\nفقد قيل: ليس المرتكب ذنبا عن جهل كمن يرتكبه عن علم ..."}, {"a": [147], "v": 1, "p": 338, "ev": 1, "ep": 339, "sid": 339, "t": "قوله عز وجل:\n﴿ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ﴾⟪2:147⟫ الآية (147) - سورة البقرة.\nالامتراء من) مريت الناقة) إذا مسحت ضرعها، وبه شبه مري الريح السحاب الممطر، ومرى الفارس فرسه للعدو، واستعير الممتري للمتردد، وفي الحكم، ولهذا استعمل فيه المتحير، وهو من حار إذا رجع، وبين أن كل حق هو من الله تعالى، إما بإبداعه وإيجاده وصنعه، وإما بأمره وإما توفيقه، وقوله: ﴿فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ﴾⟪2:147⟫ ليس بنهي عن الشك، وإذ كان ذلك ليس بقصد من الشاك، بل هو حث على اكتساب المعارف المزيلة للشك واستعمالها، وعلى ذلك قوله تعالي: ﴿إِنِّيٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلۡجَٰهِلِينَ﴾⟪11:46⟫\n⟦1:339⟧"}, {"a": [148], "v": 1, "p": 339, "ev": 1, "ep": 340, "sid": 340, "t": "قوله - عز وجل -:\n﴿وَلِكُلّٖ وِجۡهَةٌ هُوَ مُوَلِّيهَاۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ أَيۡنَ مَا تَكُونُواْ يَأۡتِ بِكُمُ ٱللَّهُ جَمِيعًاۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ﴾⟪2:148⟫\nالآية: (148) - سورة البقرة.\nأي: لكل أمة، وقيل لكل نبي وجهته، وقيل قبلة، وقيل: شريعة، وذلك في المعنى واحد، وهو ضمير\nلله- عز وجل- أي الله موليها إياه، وقيل: ضمير للكل: أي كل موالي جهته، وقرئ: ﴿هُوَ مَوۡلَىٰهُ﴾⟪66:4⟫\nفيكون هو ضمير ضمير الكل ولا يحتاج إلى تقدير ضمير أخر، وقيل: معنى: ﴿وَلِكُلّٖ وِجۡهَةٌ﴾⟪2:148⟫ أي\nللناس كلهم الآن وجهة، وهي الإسلام تنبيها أن الأديان به نسخت، نحو: ﴿إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلۡإِسۡلَٰمُۗ﴾⟪3:19⟫، وقوله: ﴿وَمَن يَبۡتَغِ غَيۡرَ ٱلۡإِسۡلَٰمِ دِينٗا فَلَن يُقۡبَلَ مِنۡهُ﴾⟪3:85⟫ وفي الآية قول آخر، وهو أن الله تعالى قيض الناس في أمور دنياهم وأخراهم لأحوال متفاوتة، وجعل بعضهم أعوان بعض فيها، فواحد يزرع، وآخر يطحن، وأخر يخبز وكذلك في أمر الدين، واحد يجمع الحديث، وواحد يطلب الفقه، والثالث يطلب الأصول وهم في الظاهر مختارون وفي الباطن مسخرون وإليه أشار النبي بقوله: \" كل ميسر لما خلق له \" وجعل للكل سبيلا للوصول إليه تلالي، وإذا راعى ما هو بصلاة وأدى الأمانة فيه، ولهذا سئل بعض الصالحين عن تفاوت الناس في أفعالهم، فقال: في ذلك طريق إلى الله تعالي وصل إليه، أراد أن يعمرها بعباده فبين أن لكل طريقا إذا تجرى فيه وجه الله تعالي وعلى ذلك قوله: ﴿لِكُلّٖ جَعَلۡنَا مِنكُمۡ شِرۡعَةٗ وَمِنۡهَاجٗاۚ﴾⟪5:48⟫، وقوله: ﴿فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ﴾⟪2:148⟫، كقوله: ﴿وَسَارِعُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ﴾⟪3:133⟫ وقوله: ﴿وَٱبۡتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلۡأٓخِرَةَۖ﴾⟪28:77⟫ وقوله: ﴿أَيۡنَ مَا تَكُونُواْ يَأۡتِ بِكُمُ ٱللَّهُ جَمِيعًاۚ﴾⟪2:148⟫ يعني أي شغل تحريتم، وحيثما صرفتم، وأي معبود اتخذتم فإنكم مجموعون ومحاسبون عليها ...\n⟦1:340⟧"}, {"a": [149], "v": 1, "p": 340, "ev": 1, "ep": 341, "sid": 341, "t": "قوله - عز وجل -:\n﴿وَمِنۡ حَيۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ وَإِنَّهُۥ لَلۡحَقُّ مِن رَّبِّكَۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ﴾⟪2:149⟫\nالآية: (149) - سورة البقرة.\nإن قيل: ما وجه تكرير (فول وجهكم) قيل: إعادة ذلك لحكمة لطيفة، وهو أنه ذكر لتغيير القبلة ثلاث علل من قوله: ﴿سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ﴾⟪2:142⟫ إلى قوله: ﴿وَلَعَلَّكُمۡ تَهۡتَدُونَ﴾⟪2:150⟫ - الأولى: إكرامه تعالى نبيه - عليه السلام- إن ولاه قبلة أبيه إبراهيم ابتغاء مرضاته، وهو قوله: ﴿قَدۡ نَرَىٰ تَقَلُّبَ وَجۡهِكَ﴾⟪2:144⟫ والثانية: إخباره أن لكل صاحب دعوة قبلة وهو قوله: ﴿وَلِكُلّٖ وِجۡهَةٌ﴾⟪2:148⟫، والثالثة: قطع حجة معانديه وهو قوله: ﴿لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيۡكُمۡ حُجَّةٌ﴾⟪2:150⟫، فقرن بذكر في علة معلولها الذي هو الفرض، وذلك قوله: ﴿فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ﴾⟪2:149⟫ لقولك: إن هذا فرض لسبب كذا، وفرض لسبب كذا، فيعتد المعلوم مع العلة، وهذا أبلغ من قول من قال: لما طال القصة، واعترض فيما بينها ما فيه زيادة بيان أعاد الحكم نحو: ﴿وَلَمَّا جَآءَهُمۡ كِتَٰبٞ مِّنۡ عِندِ ٱللَّهِ﴾⟪2:89⟫ إلى قوله: ﴿فَلَمَّا جَآءَهُم مَّا عَرَفُواْ﴾⟪2:89⟫، وأنه أعاد \" لما جاءهم \" وأشار بقوله: ﴿وَإِنَّهُۥ لَلۡحَقُّ مِن رَّبِّكَۗ﴾⟪2:149⟫ إلي تحقيق ما قدمه، فبين أنه إذا كانت الحكمة تقتضي أن لكل صاحب شرع قبلة تختص بها وأنت صاحب شرع، فتغيير القبلة لك حق،\nإن قيل: لم خص الأول بلفظ الرب، والثاني بلفظ الله؟\nقيل: لأن الأول لما نبهنا على الاستدلال على حكمته بالنظر إلى أفعاله ذكر لفظ الرب المقتضى [للنعم المسطر فيها إلى المنعم] ويستدل بها عليه، ولما انتهى إلى ذكر الوعيد ذكر لفظ الله تعالى المقتضي للعبادة التي من أحل بها عليه استحق أليم عقاب.\n⟦1:341⟧"}, {"a": [150], "v": 1, "p": 341, "ev": 1, "ep": 343, "sid": 342, "t": "قوله - عز وجل -:\n﴿وَمِنۡ حَيۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيۡكُمۡ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِي وَلِأُتِمَّ نِعۡمَتِي عَلَيۡكُمۡ وَلَعَلَّكُمۡ تَهۡتَدُونَ﴾⟪2:150⟫\nالآية (150) - سورة البقرة.\nفإن قيل: لم كرر قوله: ﴿وَحَيۡثُ مَا كُنتُمۡ فَوَلُّواْ وُجُوهَكُمۡ شَطۡرَهُۥ﴾⟪2:150⟫، قيل: حث بأحدهما على التوجه نحو القبلة بالقلب والبدن في أي مكان حصل الإنسان نائيا كان عنها أو دانيا منها، وذلك حال الاختيار والتمكن، وحث بالآخر على التوجه بالقلب نحوه عند اشتباه القبلة، وفي حال المسامعة، وفي صلاة النافلة في حال المسير في السفر وعلى الراحلة ...\nإن قيل: كيف استثنى الذين ظلموا وذلك يقتضي أن يكون لهم حجة،؟ قيل: الحجة ههنا موضوعة موضع الاحتجاج نحو: ﴿حُجَّتُهُمۡ دَاحِضَةٌ﴾⟪42:16⟫ ومعناه: لئلا يحتج عليكم أحد إلا وهو وظالم، وقوله: (لئلا) إبانة عن الغرض، والعاقل لا يقصد إلا عارضا يصح أن يصيبه، فالمؤمن لا يقصد بذكر الحجة أن يكف الناس بها عن الاحتجاج لعلمه أن منهم معاندا لا يبالي بارتكابه الباطل، والله تعالى لا يأمر بدلك لكونه غير مستطاع، فكأنه قال: أقصدوا بالحجة دفع الناس إلا الظالمين، وقيل الظالمون إشارة إلى مشركي العرب حيث قالوا:\n\" إن محمد عاد إلى فبلتنا \"، وقد استدل بعضهم على أن الناس ههنا لمشركي قريش بما روي في الخبر أن كل ما في القرآن من قوله ﴿يَٰٓأَيُّهَا ٱلنَّاسُ﴾ فمخاطبة لأهل مكة، وما فيه من ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ﴾⟪2:153⟫ فمخاطبة لأهل المدينة، وقول من قال تقديره: ﴿لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيۡكُمۡ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡ﴾⟪2:150⟫.\n⟦1:342⟧\nإلا حجة الذين ظلموا، قال: والظالم لا حجة له في الحقيقة فصار كقول الشاعر:\nولا عيب فيهم غير أن سيوفهم\n....\nبهن فلول\nالبيت راجع إلى الأول وأما قول أبي عبيدة إن تقديره \" والذين ظلموا \" فإن أراد أن معناه هذا على تقدير ما تقدم فصحيح، وإبل أراد أن معناه بمعنى \" الواو \" هبعيد، وقول الشاعر الذي احتج به وهو قوله:\nما بالمدينة دار وأحدة\nدار الخليفة إلا دار مروان\nفتقديرها: ما بالمدينة دار إلا دار مروان غير واحده، وهي دار الخليفة، فقد أثبت دارين فصار من حيث المعنى، كما قال: ليس معنى إلا معنى الواو، وإن قيل: أي حجة لهم على ألكفار إذا فعلوا ذلك، وأي حجة تسقط عنهم، قيل لما ذكر الله تعالى: ﴿فَأَيۡنَمَا تُوَلُّواْ فَثَمَّ وَجۡهُ ٱللَّهِۚ﴾⟪2:115⟫، ومن أن التوجه إلي الجوانب سواء في المعقول أبان أق إنما قصرهم على جانب واحد لئلا يختلف توجيههم فيحتج عليهم الكفار بالاختلاف، ويقولون: ما بالكم تصلون إليها تارة وإلى غيرها أخرى، وقوله: ﴿فَلَا تَخۡشَوۡهُمۡ﴾⟪2:150⟫ أي لا تراقبوهم ولا تستحيوا منهم، وذلك لما علم أن كلامهم عناد للعقيدة عند ظهور الحجة عن التزامها، فقال لهم ذلك والخشية قد تجري مجرى المراقبة والاستحياء في قوله: ﴿وَتَخۡشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخۡشَىٰهُۖ﴾⟪33:37⟫ وقوله: ﴿وَلِأُتِمَّ نِعۡمَتِي عَلَيۡكُمۡ﴾⟪2:150⟫ معطوف على قوله: ﴿لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيۡكُمۡ حُجَّةٌ﴾⟪2:150⟫ وإتمام نعمته هو أن نعم الله تعالى ضربان: أحدهما موهوب، والآخر مكتسب،\n⟦1:343⟧\nفالموهوب: كجودة الحفظ والفهم وصحة البدن والجاه، وكل ذلك لا يستحق بحصوله الحمد، ولا بفواته الذم، والمكتسب كالعلم والعمل الصالح المتوصل بهما إلى الثواب وهو الإيمان، وبه يستحق المدح والذم، فبين تعالى أنه إذا ائتمرتم في أمر القبلة، وصلتم إلى الحالة التي يحصل لكم الخشية المشار إليها بقوله:\n﴿إِنَّمَا يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْۗ﴾⟪35:28⟫ فقد أتممت نعمتي عليكم) واستتممتموها)"}, {"a": [151], "v": 1, "p": 343, "ev": 1, "ep": 344, "sid": 344, "t": "قوله عز وجل:\n﴿كَمَآ أَرۡسَلۡنَا فِيكُمۡ رَسُولٗا مِّنكُمۡ يَتۡلُواْ عَلَيۡكُمۡ ءَايَٰتِنَا وَيُزَكِّيكُمۡ وَيُعَلِّمُكُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَيُعَلِّمُكُم مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ﴾⟪2:151⟫\nالآية (151) - سورة البقرة.\nما مع ما بعده مصدر، أي: كإرسالنا، والكاف فيه متعلق بقوله ولأتم نعمتي عليكم، أي إذا أنتم ائتمرتم في أمر القبلة وخشيتم الله دون الناس أتم عليكم كلمته كنعمته بإرسال رسول هكذا تنبيها أن النعمة في بعثته ودعائه العالم إلى دين مخالف لدينهم، ووعدكم أته سيظهر دينه على الأديان كان أعظم من تغيير القبلة، وقد وفى بذلك، وقيل: تتعلق الكاف بقولها \" اذكروني \" وهو بعيد ...\nإن قيل: كيف أخر فيما حكى عن إبراهيم عليه السلام قوله: ﴿رَبَّنَا وَٱبۡعَثۡ فِيهِمۡ رَسُولٗا﴾⟪2:129⟫ ذكر التزكية عن تعليم الكتاب والحكمة وقدمها هاهنا؟ قيل: التزكية من الله عز وجل ضربان، أحدهما الشهادة بطهارة الإنسان، وذلك يكون بتزكية الإنسان نفسه، وذلك مؤخر عن تحصيل الإنسان الكتاب والحكمة والعمل بهما، وإياهما عنى إبراهيم- عليه السلام- في دعائه، فلذلك أخر، والثانية من الله - عز وجل- تبين أحكامه الشرعية، ومن العبد العمل بها، وذلك متقدم علي معرفة حقائق الكتاب والحكمة وهي المعنية ههنا، فلهذا قدم\n⟦1:344⟧\nأن قيل: وما معنى ﴿وَيُعَلِّمُكُم مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ﴾⟪2:151⟫؟\nوهل ذلك إلا الكتاب والحكمة؟\nقيل: عنى بقوله: ﴿مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ﴾⟪2:151⟫ اللعوم التي لا طريق إلى تحصيلها إلا بالوحي على ألسنة الأنبياء، ولا سبيل إلى إدراك جزئياتها ولا كلياتها إلا به، وعنى بالحكمة والكتاب ما للعقل مدخل في معرفته شيء منه، وأعاد ذكره يعلمكم مع قوله: ﴿مَّا لَمۡ تَكُونُواْ تَعۡلَمُونَ﴾⟪2:151⟫ تنبيها أنه علم مفرد عن المتقدم ذكره. . . قوله - عز وجل -:"}, {"a": [152], "v": 1, "p": 344, "ev": 1, "ep": 346, "sid": 345, "t": "﴿فَٱذۡكُرُونِيٓ أَذۡكُرۡكُمۡ وَٱشۡكُرُواْ لِي وَلَا تَكۡفُرُونِ﴾⟪2:152⟫\nالآية (152) - سورة البقرة.\nالذكر حضور الشر بالقلب والقول، فلهذا قيل: الذكر ذكران ذكر باللسان، وذكر بالقلب، وقد\nيكون ذلك لحضور لا عن نسيان، وقل يكون عن نسيان، ولهذا فيل: الذكر ذكران، ذكر لكن نسيان،\nوذكر لا عن نسيان.\nوإلى الثاني ذهب الشاعر في قوله:\nوكيف أذكره إذ لست أنساه؟\nوقال بعض العلماء: لما خص الله هذه الأمة بفضل قوة زائدة على ما لبني إسرائيل، قال لبني إسرائيل: ﴿ٱذۡكُرُواْ نِعۡمَتِيَ ٱلَّتِيٓ أَنۡعَمۡتُ عَلَيۡكُمۡ﴾، فأمرهم بتذكر نعمته المنبهة عن الغفلة لينظروا منها إليه وقال لهذه الأمة:) فاذكروني)، فأمرهم أن في يذكروه بلا واسطة\nإن قيل: ما الفرق بين شكرت لزيد، وشكرت زيدا؟ قيل: شكرت له هو أن يعتبر إحسانه الصادر عنه فيثنى عليه بذلك وشكرته: إذا لم تلتف إلى فعله، بل تجاوزت إلى ذكر ذاته دون اعتبار أفعاره، فهو أبلغ من شكرت له، إذ قد يكون\n⟦1:345⟧\nللإنسان فعل في الظاهر محمود، ثم لا يكون ذلك الإنسان على الإطلاق محمودا، وإنما قال:) واشكروا لي)، ولم يقل: (واشكروني) علما بقصورهم عن إدراكه بل عن إدراك الآية كما قال: ﴿وَإِن تَعُدُّواْ نِعۡمَتَ ٱللَّهِ لَا تُحۡصُوهَآۗ﴾⟪14:34⟫ فأمرهم أن يعدوا بعض أفعاله في الشكر له، وشكر الله عز وجل- أصعب عبادة أشرفها، ولهذا قيل: غاية شكر الله الاعتراف بالعجز عنه، فكل نعمة يمكن شكرها إلا نعمة الله، فإن شكرها نعمه منه، فذلك بتوفيقه، فإن العبد محتاج أن يشكر نعمته الثانية كشكره للأولى، وهدا يؤدي إلى مالا يتناهى، فلهذا قيل: لا يقدر عليه، ولصعوبة الشكر قال: ﴿وَقَلِيلٞ مِّنۡ عِبَادِيَ ٱلشَّكُورُ﴾⟪34:13⟫، ولم يثن على أنبيائه وأوليائه بالشكر إلا على أثنين، على نوح حيث قال: ﴿إِنَّهُۥ كَانَ عَبۡدٗا شَكُورٗا﴾⟪17:3⟫، وعلى إبراهيم حيث قال: ﴿شَاكِرٗا لِّأَنۡعُمِهِۚ﴾⟪16:121⟫، فذكر ذلك بلفظ أدى العدد تنبيها على شرف هذه المنزلة وصعوبتها ...\nإن قيل: علم عطف قول: ﴿فَٱذۡكُرُونِيٓ أَذۡكُرۡكُمۡ﴾⟪2:152⟫؟\nقيل: على قوله: ﴿فَوَلُّواْ وُجُوهَكُمۡ﴾⟪2:150⟫، وذلك أنه لما أمرنا باستقبال القبلة، وبين العلة وأنه يريد أن يتم نعمته عليكم كما أنعم ببعثته رسوله أعاد النظم الذي هو الأمر، فأمر بالذكر الواجب بعضه في الصلاة، وبعضه في غيرها، وإن قيل: ولم قال بعده: ﴿وَلَا تَكۡفُرُونِ﴾⟪2:152⟫ ولم يقتصر على أحد اللفظين؟ قيل: لما كان الإنسان قد يكون شاكرا في شي ما، وكافرا في غيره، فيصح أن يوصف بهما على حسب النظر إلى فعليه، فلو اقتصر على قوله: ﴿وَٱشۡكُرُواْ لِي﴾⟪2:152⟫ لكان يجوز أن يتوهم إن من شكره مرة أو على نعمة ما فقد امتثل، ولو اقتصر على قوله: ﴿وَلَا تَكۡفُرُونِ﴾⟪2:152⟫ لكان يجوز أن يتوهم أن ذلك نهى عن تعاطي قبيح دون حث على الفعل الجميلة فجمع بينهما لإزالة هده الشبهة، ولأن في قوله:\n⟦1:346⟧\n﴿وَلَا تَكۡفُرُونِ﴾⟪2:152⟫ نهيأ عن الكفر المطلق، وذلك معنى [زائد على قوله ﴿وَٱشۡكُرُواْ لِي﴾⟪2:152⟫ وقدم قوله] ﴿وَٱشۡكُرُواْ لِي﴾⟪2:152⟫ وأخر قوله: ﴿وَلَا تَكۡفُرُونِ﴾⟪2:152⟫ تنبيها على أن ترك الشكر كفران ...\nإن قيل: فلم قال: ﴿وَلَا تَكۡفُرُونِ﴾⟪2:152⟫ ولم يقل (ولا تكفروا لي)؟ قيل: لأنه يقتصر من العبد على شكر نعمه، ولا يقتصر منه على أن لا يكفر نعمه، بل نهى عن الكفر به أكثر مما نهى عن كفر نعمه، إذ قد يعفو عن كفر بعض النعم ولا يعفو عن الكافر المطلق. . . قوله - عز وجل -:"}, {"a": [153], "v": 1, "p": 346, "ev": 1, "ep": 347, "sid": 347, "t": "﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ﴾⟪2:153⟫\nالآية (153) - سورة البقرة.\nقد تقدم الكلام في الصبر والصلاة وأنواعهما، فحث الله تعالى على الصبر، إذ هو ذريعة إلي فعل كل خير ويبدأ كل فضل، فإن أول التوبة الصبر عن العاصي، وأول الزهد الصبر عن مناجاة الدنيا ، وأول الإرادة الصبر على طلب ما سوى الله، ولهذا قال عليه السلام: (الصبر من الإيمان بمنزلة الرأس من الجسد)، وقال: (والصبر خير كله) والصلاة هي المقتضية للخشوع والداعية إلي ترك الفحشاء قال تعالى: ﴿إِنَّ ٱلصَّلَوٰةَ تَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۗ﴾⟪29:45⟫ ولا أمر بالذكر والشكر حث على الاستعانة بالصبر والصلاة - تنبيها أنه بهما يتوصل إليه، فإن الصبر مبدأ الإيمان، والشكر منتهاه ولهذا قال عليه السلام: \" الصبر نصف الإيمان \" ثم قال: ﴿إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ﴾⟪2:153⟫ فضمن صحبته إياهم تنبيها على قرب فيضه وتوفيقه، كما قال:\n⟦1:347⟧\n﴿وَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ فَإِنَّكَ بِأَعۡيُنِنَاۖ﴾⟪52:48⟫ تنبيها أنه يراعيهم بالعناية،\nإن قيل: لم قال: ﴿إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ﴾⟪2:153⟫ ولم يقل: \" مع المصلين \" وقال في أخرى: ﴿وَٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ وَإِنَّهَا لَكَبِيرَةٌ﴾⟪2:45⟫ فاعتبر الصلاة دون الصبر؟ قيل:\nلما كان فعل الصابرين أشرف وأعلى من الصبر، إذ قد ينفك الصبر من الصلاة ولا تنفك الصلاة من الصبر ذكر ههنا الصابرين، فمعلوم أنه تعالى إذا كان مع الصابر، كان لا محالة مع المصلي أكثر ثم قال: ﴿وَإِنَّهَا لَكَبِيرَةٌ﴾⟪2:45⟫ فذكر الصلاة دون الصبر تنبيها أنها أشرف منزلة من الصبر فقد ترك توفية حق الصلاة من تصبر في كثير من الأحوال."}];
